local config = {
  ui_story_5010_50100101_1_dialog_content = "\"Sebagai makhluk hidup, kita harus mencintai, mengasihi, dan menghargai sesama makhluk.\"",
  ui_story_5010_50100101_2_dialog_content = "\"Dengan demikian, kami melakukan apa yang kami anggap benar, dan tidak perlu berterima kasih kepada kami.\"",
  ui_story_5010_50100101_3_dialog_content = "\"Jaga dirimu, PlayerName muda.\"",
  ui_story_5010_50100101_4_dialog_content = "Wow... Surat dari <color=#FFB400>Persekutuan Lin</color> benar-benar menunjukkan bahwa mereka adalah keluarga yang sangat beradab!",
  ui_story_5010_50100101_5_dialog_content = "Kapan-kapan, aku juga harus menulis surat untuk Vice dengan gaya bahasa seperti ini...",
  ui_story_5010_50100101_6_dialog_content = "\"Halo, Vice, kiranya bagaimanakah kabarmu belakangan ini? Apakah kau sudah mulai terbiasa dengan rutinitas latihanmu di Illumina?\"",
  ui_story_5010_50100101_7_dialog_content = "\"Bagaimanapun, sebagai kawan, mempelajari seni memasak yang halus adalah yang paling penting...\"",
  ui_story_5010_50100101_8_dialog_content = "\"Burung gembul! Gembul!\"",
  ui_story_5010_50100101_9_dialog_content = "Hai! Kasar!",
  ui_story_5010_50100101_10_dialog_content = "Hah?",
  ui_story_5010_50100101_11_dialog_content = "Yaaa!",
  ui_story_5010_50100101_12_dialog_content = "Mau dengar leluconku duluan?",
  ui_story_5010_50100101_13_dialog_content = "Leluconku super-duper-ekstra-lucu! Berat badan Yoshi sampai turun hampir sekilo gara-gara tertawa mendengarnya!",
  ui_story_5010_50100101_14_dialog_content = "Mungkin kapan-kapan saja, ya... Eh, ada surat menyembul dari tasmu, tuh.",
  ui_story_5010_50100101_15_dialog_content = "Sepertinya ini ditujukan untuk... untukku? Sini, coba kulihat.",
  ui_story_5010_50100101_16_dialog_content = "Kau bahkan tak punya waktu untuk mendengarkan sedikit lelucon? Ya sudah!",
  ui_story_5010_50100101_17_dialog_content = "Nih, suratmu!",
  ui_story_5010_50100101_18_dialog_content = "Dari <color=#FFB400>Shadowlord</color> sendiri!",
  ui_story_5010_50100101_19_dialog_content = "Mereka secara khusus meminta saya melihat Anda membaca semuanya.",
  ui_story_5010_50100101_20_dialog_content = "Makanya, cepatlah! Waktuku tak banyak!",
  ui_story_5010_50100101_21_dialog_content = "Ba-baiklah! Aku penasaran, apa isinya, ya? Pasti hal penting...",
  ui_story_5010_50100101_22_dialog_content = "Halo, PlayerName,",
  ui_story_5010_50100101_24_dialog_content = "\"Berdasarkan berbagai perbuatanmu...\"",
  ui_story_5010_50100101_25_dialog_content = "\"Baik Illumina Federation maupun Lumopolis sama-sama mengakuimu sebagai satu-satunya perwakilan kaum Caelestite. Tentu saja, demikian pula Umbraton...\"",
  ui_story_5010_50100101_26_dialog_content = "Ya ampun, cepat, dong! Masih banyak surat yang harus kuantarkan, tahu!",
  ui_story_5010_50100101_27_dialog_content = "\"Sebagai perwakilan Umbraton, dengan ini kunyatakan bahwa semua aset Caelestite yang disimpan di Umbraton menjadi milikmu sepenuhnya, orang terakhir dari kaum Caelestite...\"",
  ui_story_5010_50100101_28_dialog_content = "\"Kau bisa menggunakan surat ini sebagai bukti hak kepemilikanmu atas aset tersebut, dan Markas Besar Umbraton Guild akan mengurus semua prosedur logistiknya...\"",
  ui_story_5010_50100101_29_dialog_content = "\"Lokasi markas adalah... Orang yang bertanggung jawab atas masalah ini adalah... Informasi kontak terminal mereka adalah sebagai berikut...\"",
  ui_story_5010_50100101_30_dialog_content = "\"... Dan <color=#FFB400>Bethel</color> akan mengawalmu ke bank Guild serta mengurus semua dokumen penyerahan warisannya...\"",
  ui_story_5010_50100101_31_dialog_content = "Tujuh belas Kunang-kunang... delapan belas Kunang-kunang...",
  ui_story_5010_50100101_32_dialog_content = "\"Hormat kami, Istvan.\"",
  ui_story_5010_50100101_33_dialog_content = "Aset Caelestite...?",
  ui_story_5010_50100101_34_dialog_content = "Anu... Eho? Memangnya aset apa yang dimiliki kaum Caelestite di Umbraton?",
  ui_story_5010_50100101_35_dialog_content = "Entahlah.",
  ui_story_5010_50100101_36_dialog_content = "Kalau begitu, apa kau tahu berapa lama waktu yang dibutuhkan Guild untuk mengurus semua dokumennya?",
  ui_story_5010_50100101_37_dialog_content = "Sama sekali tak tahu!",
  ui_story_5010_50100101_38_dialog_content = "Kalau begitu... Apa kau tahu siapa si <color=#FFB400>Bethel</color> ini?",
  ui_story_5010_50100101_39_dialog_content = "Aha! Kalau itu, aku tahu!",
  ui_story_5010_50100101_40_dialog_content = "Dia bertanggung jawab atas markas Persekutuan, dan dia adalah putri angkat Shadowlord!",
  ui_story_5010_50100101_41_dialog_content = "Saya mendengar bahwa dia kembali ke Umbraton setelah belajar di Lumopolis, dan dia membawa beberapa anak anjing yang lucu!",
  ui_story_5010_50100101_42_dialog_content = "Anak angkat? Sebenarnya Shadowlord punya berapa putri angkat, sih...?",
  ui_story_5010_50100101_43_dialog_content = "Yah, itu tak penting!",
  ui_story_5010_50100101_44_dialog_content = "Oh, iya! Lady <color=#FFB400>Naroxel</color> juga memintaku untuk menyampaikan pesan kepadamu!",
  ui_story_5010_50100101_45_dialog_content = "Kenapa dia tidak memberitahuku sendiri...?",
  ui_story_5010_50100101_46_dialog_content = "Dia sangat sibuk, tahu! Nah, dengarkan...",
  ui_story_5010_50100101_47_dialog_content = "\"Salam, PlayerName.\"",
  ui_story_5010_50100101_48_dialog_content = "\"Telah menjadi perhatian saya bahwa satu set tertentu <color=#FFB400>komponen ruang simulasi</color> akan segera terdaftar dalam lelang bawah tanah di Umbraton.\"",
  ui_story_5010_50100101_49_dialog_content = "\"Sejauh yang kutahu, komponen semacam itu biasanya digunakan untuk memodifikasi atau bahkan meng-upgrade Colossus.\"",
  ui_story_5010_50100101_50_dialog_content = "\"Kalau tertarik, mungkin sebaiknya kau melihatnya saja langsung. Mungkin komponen itu bisa bermanfaat untuk Soroz?\"",
  ui_story_5010_50100101_51_dialog_content = "\"Semoga alam selalu melindungimu... Kawanmu, Naroxel.\"",
  ui_story_5010_50100101_52_dialog_content = "\"<color=#FFB400>Komponen ruang simulasi</color>\"?... Eh, Eho?",
  ui_story_5010_50100101_53_dialog_content = "Kaok? Apa lagi?",
  ui_story_5010_50100101_54_dialog_content = "Apakah Anda tahu tentang lelang bawah tanah?",
  ui_story_5010_50100101_55_dialog_content = "Tentu saja aku tahu! Jelas, itu acara lelang... dan digelar di bawah tanah!",
  ui_story_5010_50100101_56_dialog_content = "Kalau ke sana dan melihatnya sendiri, kau pasti akan tahu, 'kan? Ah, kau ini lemot sekali, sih.",
  ui_story_5010_50100101_57_dialog_content = "Aku harus pergi sekarang! Masih ada delapan belas surat yang harus kuantarkan hari ini!",
  ui_story_5010_50100101_58_dialog_content = "Baiklah, terima kasih atas... Oh, rupanya dia sudah pergi. Pasti enak sekali kalau punya sayap seperti itu...",
  ui_story_5010_50100101_59_dialog_content = "Hmm... banyak yang harus dipikirkan sekarang. Aku butuh waktu...",
  ui_story_5010_50100101_60_dialog_content = "Markas besar Persekutuan, pelelangan bawah tanah...",
  ui_story_5010_50100101_61_dialog_content = "Oh! Aku juga bisa mampir ke Lin Guild dan bertukar kabar dengan mereka!",
  ui_story_5010_50100101_62_dialog_content = "\"Silakan hubungi nomor berikut melalui terminal, dan ketua Persekutuan akan menemui Anda di luar Umbraton...\"",
  ui_story_5010_50100101_63_dialog_content = "Sepertinya, berikutnya kita akan singgah di <color=#FFB400>Umbraton</color>!",
  ui_story_5010_50100201_1_dialog_content = "Halo? Apakah ini PlayerName? Ini Betel, dari Persekutuan Umbraton.",
  ui_story_5010_50100201_2_dialog_content = "Ha-halo!",
  ui_story_5010_50100201_3_dialog_content = "Silakan mendarat di sisi timur <color=#FFB400>Bendungan Bekas Luka</color>. Aku akan menunggumu di sana.",
  ui_story_5010_50100201_4_dialog_content = "Bukan masalah!",
  ui_story_5010_50100201_5_dialog_content = "Umbraton terlihat sangat mengesankan dari sudut ini.",
  ui_story_5010_50100201_6_dialog_content = "Umbraton... Kota yang dikenal sebagai Bayangan Lumopolis.",
  ui_story_5010_50100201_7_dialog_content = "<color=#e8d9bb>Sebentar lagi kita akan sampai di tujuan. Harap konfirmasikan zona pendaratanmu sebelum kita sampai di sana.</color>",
  ui_story_5010_50100201_8_dialog_content = "Oh, tidak... Aku benar-benar lupa menanyakan lokasi Bendungan Bekas Luka.",
  ui_story_5010_50100201_9_dialog_content = "Sepertinya aku harus mencarinya sendiri...",
  ui_story_5010_50100201_10_dialog_content = "Halo lagi. Kau pasti PlayerName. Aku Bethel.",
  ui_story_5010_50100201_11_dialog_content = "Ya! H-Hai...",
  ui_story_5010_50100201_12_dialog_content = "Dan ini pasti Colossus-mu... Dia memang megah, persis seperti yang kudengar dari cerita orang-orang. Pasti sulit memilotinya, ya?",
  ui_story_5010_50100201_13_dialog_content = "Sepertinya kau kesulitan mendaratkannya.",
  ui_story_5010_50100201_14_dialog_content = "Ti-tidak juga, sih, aku hanya sedikit tersesat. Aku jarang mendatangi Umbraton...",
  ui_story_5010_50100201_15_dialog_content = "Jujur saja, aku sendiri juga hampir tersesat saat menuju kemari.",
  ui_story_5010_50100201_16_dialog_content = "Umbraton pasti telah banyak berubah dalam beberapa tahun terakhir...",
  ui_story_5010_50100201_17_dialog_content = "Tapi, tak perlu berpanjang lebar soal itu. Silakan, lewat sini.",
  ui_story_5010_50100201_18_dialog_content = "(Kalau saja aku tahu dia akan bersikap formal begini, pasti aku sudah berdandan lebih baik...)",
  ui_story_5010_50100201_19_dialog_content = "Kalau begitu... apa sekarang kita akan pergi ke markas besar?",
  ui_story_5010_50100201_20_dialog_content = "Oh, ya... Apa kau bisa memberitahuku apa sebenarnya aset Caelestite itu?",
  ui_story_5010_50100201_21_dialog_content = "Menurut buku besar, aset itu berupa sejumlah peti. Hanya pemiliknyalah yang boleh membuka dan memastikan isinya.",
  ui_story_5010_50100201_22_dialog_content = "Markas Besar Persekutuan Umbraton... Maafkan saya, tetapi apakah Anda mengelola semua operasi Persekutuan? Apakah lelang bawah tanah juga berada di bawah yurisdiksi Anda?",
  ui_story_5010_50100201_23_dialog_content = "Lelang bawah tanah?",
  ui_story_5010_50100201_24_dialog_content = "Walau aku tak tahu dari mana kaudengar istilah itu, sayangnya tak banyak informasi yang bisa kuberitahukan kepadamu tentang itu.",
  ui_story_5010_50100201_25_dialog_content = "Jangan-jangan, kau berniat melelang aset Caelestite yang akan kauklaim itu?",
  ui_story_5010_50100201_26_dialog_content = "Ah! A-aku tidak berniat begitu! Hanya saja, aku mendengar ada orang yang mendaftarkan sejumlah barang Caelestite untuk dilelang... Makanya, aku menanyakannya kepadamu.",
  ui_story_5010_50100201_27_dialog_content = "Itu akan jauh di bawah kita. Persekutuan Umbraton tidak akan pernah terlibat dalam penjualan properti orang lain tanpa izin.",
  ui_story_5010_50100201_28_dialog_content = "Be-benar.",
  ui_story_5010_50100201_29_dialog_content = "Kalau tak keberatan, tolong agak cepat sedikit.",
  ui_story_5010_50100201_30_dialog_content = "...",
  ui_story_5010_50100201_31_dialog_content = "(Aku merasa sepertinya aku harus bilang sesuatu... Tapi, apa yang harus kubicarakan, ya?)",
  ui_story_5010_50100201_32_option_content = "Tanyakan tentang Lin Guild",
  ui_story_5010_50100201_33_dialog_content = "Betel...? Apakah Anda akrab dengan <color=#FFB400>Persekutuan Lin</color>?",
  ui_story_5010_50100201_34_dialog_content = "Tentu saja.",
  ui_story_5010_50100201_35_option_content = "Tanyakan tentang bendungan",
  ui_story_5010_50100201_36_dialog_content = "Bendungan yang tadi kita lewati itu besar sekali! Apa orang-orang Umbraton sendiri yang membangunnya?",
  ui_story_5010_50100201_37_dialog_content = "Bendungan itu dibangun atas perintah Shadowlord untuk mengantisipasi kondisi cuaca yang tidak wajar.",
  ui_story_5010_50100201_38_dialog_content = "Di bawah bimbingannya, masing-masing guild besar berinvestasi dalam proyek tersebut, dermawan terbesar adalah the <color=#FFB400>Keluarga Lin</color>.",
  ui_story_5010_50100201_39_dialog_content = "Kalau begitu... Lin Guild...",
  ui_story_5010_50100201_40_dialog_content = "Ya? Kau tertarik dengan mereka?",
  ui_story_5010_50100201_41_dialog_content = "Saya hanya mendengar beberapa hal di sana-sini tentang mereka. Lagi pula, mereka selalu cantik... sulit dipahami.",
  ui_story_5010_50100201_42_dialog_content = "Mereka berspesialisasi dalam produk buatan tangan. Porselen mereka memiliki kualitas terbaik, begitu pula kipas lipatnya.",
  ui_story_5010_50100201_43_dialog_content = "Mungkinkah kau tertarik untuk berbisnis dengan Lin Family?",
  ui_story_5010_50100201_44_dialog_content = "Bu-bukan, bukan begitu... Dulu, mereka pernah membantuku dalam suatu hal yang sangat penting, jadi aku ingin mampir dan bertukar kabar dengan mereka.",
  ui_story_5010_50100201_45_dialog_content = "Oh, begitu. Dalam perjalanan menuju markas besar kami, kita akan melewati Lin Guild Hall...",
  ui_story_5010_50100201_46_dialog_content = "Baguslah! Oh, iya... Dokumen apa yang harus kulengkapi di markas besar?",
  ui_story_5010_50100201_47_dialog_content = "Sederhana saja, kok. Kau juga bisa menghabiskan waktu sebanyak yang kaubutuhkan untuk memeriksa setiap buku besar dan aset, jadi tenang sajalah.",
  ui_story_5010_50100201_48_dialog_content = "Baiklah. Kuharap tempatnya tidak terlalu jauh...",
  ui_story_5010_50100201_49_dialog_content = "Tenanglah, sebentar lagi kita akan sampai.",
  ui_story_5010_50100201_50_dialog_content = "Tunggu. Frankel merasa ada sesuatu yang janggal.",
  ui_story_5010_50100201_51_dialog_content = "Frankel?",
  ui_story_5010_50100201_52_dialog_content = "Saya akrab.",
  ui_story_5010_50100201_53_dialog_content = "Sepertinya mereka mencium aroma aneh... Aroma yang familier.",
  ui_story_5010_50100201_54_dialog_content = "Aku juga bisa merasakannya... Eclipsite!",
  ui_story_5010_50100201_55_dialog_content = "Guk! Guk!",
  ui_story_5010_50100201_56_dialog_content = "Awas, Bethel!",
  ui_story_5010_50100201_57_dialog_content = "Aku bisa merasakan mereka... Para Eclipsite itu mendekat ke posisi kita, dan mereka bergerak cepat!",
  ui_story_5010_50100201_58_dialog_content = "Kau bisa merasakan gerakan mereka sejelas itu? Ini pasti kekuatan kaum Caelestite!",
  ui_story_5010_50100201_59_dialog_content = "Tenanglah...",
  ui_story_5010_50100201_60_dialog_content = "Aku akan memberantas mereka sampai tak bersisa.",
  ui_story_5010_50100202_1_dialog_content = "Tidak terasa mereka hanya berkeliaran. Lebih tepatnya...",
  ui_story_5010_50100202_2_dialog_content = "Itu hampir jika mereka langsung menuju target mereka.",
  ui_story_5010_50100202_3_dialog_content = "PlayerName, yang kaumaksud sasaran itu adalah dirimu, 'kan?",
  ui_story_5010_50100202_4_dialog_content = "Aku...",
  ui_story_5010_50100202_5_dialog_content = "Tunggu... Jumlah mereka bertambah banyak!",
  ui_story_5010_50100202_6_dialog_content = "Graaaaaagh!!",
  ui_story_5010_50100202_7_dialog_content = "Akan kubereskan yang di depan sana! Tetaplah di belakangku untuk sementara ini!",
  ui_story_5010_50100202_8_dialog_content = "Di depan sana!",
  ui_story_5010_50100202_9_dialog_content = "Graa—",
  ui_story_5010_50100202_10_dialog_content = "Apa-apaan ini? Kau masih saja berdiri setelah semua itu? Kau agak berbeda dari yang dibilang orang-orang, Caelestite.",
  ui_story_5010_50100202_11_dialog_content = "... A-apa dari tadi kau mengikuti kami?",
  ui_story_5010_50100202_12_dialog_content = "Anggota <color=#FFB400>White Flame Mercenaries</color>? Jadi... Ternyata kau bahkan menyewa seorang pengawal.",
  ui_story_5010_50100202_13_dialog_content = "Untuk menyembunyikan kehadiranmu dengan sangat baik selama ini... Aku bersyukur kamu bukan musuh kami.",
  ui_story_5010_50100202_14_dialog_content = "Aku <color=#FFB400>Luke</color>, dari White Flame Mercenaries. Naroxel memintaku untuk melindungimu, PlayerName.",
  ui_story_5010_50100202_15_dialog_content = "Melindungiku?",
  ui_story_5010_50100202_16_dialog_content = "Benar sekali! Naroxel bilang, kau ini kawan baiknya, dan kau dulu sudah membantunya.",
  ui_story_5010_50100202_17_dialog_content = "... PlayerName, aku juga sudah meminta Luke, seorang kawan lamaku, untuk membantumu...",
  ui_story_5010_50100202_18_dialog_content = "Tapi, Umbraton kan bukan zona tempur! Kenapa aku harus dilindungi?",
  ui_story_5010_50100202_19_dialog_content = "Hei, aku hanya seorang tentara bayaran. Saya tidak pernah mengajukan pertanyaan apapun.",
  ui_story_5010_50100202_20_dialog_content = "Ehem...",
  ui_story_5010_50100202_21_dialog_content = "Ah! Selamat siang, Lady Bethel dari Guild. Sudah selayaknya penerus Lord Istvan punya kemampuan tempur luar biasa sepertimu!",
  ui_story_5010_50100202_22_dialog_content = "Hmmm...",
  ui_story_5010_50100202_23_dialog_content = "Sebentar... Luke. Apa kamu tahu tentang lelang bawah tanah?",
  ui_story_5010_50100202_24_dialog_content = "Tahu sedikit, tapi aku bisa mengumpulkan informasi kalau kau memang butuh. Bagaimana?",
  ui_story_5010_50100202_25_dialog_content = "Sungguh? Baguslah kalau begitu! Begini, aku ingin mendatangi lelang itu untuk mencari tahu apakah...",
  ui_story_5010_50100202_26_dialog_content = "PlayerName, kurasa pertama-tama kita harus kembali ke markas besar dulu untuk menyelesaikan urusan utama kita!",
  ui_story_5010_50100202_27_dialog_content = "Apa kau akan terus mengawal kami dari belakang, Luke? Kurasa sekarang sudah tak ada alasan bagimu untuk terus bersembunyi.",
  ui_story_5010_50100202_28_dialog_content = "Huh, maaf. Ini memang kebiasaanku saat bekerja...",
  ui_story_5010_50100202_29_dialog_content = "Kita berhasil menjatuhkan pesawat itu!",
  ui_story_5010_50100202_30_dialog_content = "Bagus! Terus cari! Pastikan penumpangnya sudah mati. Kalau ada yang masih hidup, bawa mereka kepadaku!",
  ui_story_5010_50100202_31_dialog_content = "Rhein...",
  ui_story_5010_50100202_32_dialog_content = "Hmm?",
  ui_story_5010_50100202_33_dialog_content = "Bagaimana perkembangannya?",
  ui_story_5010_50100202_34_dialog_content = "Semua sesuai rencana.",
  ui_story_5010_50100301_1_dialog_content = "Wah, bangunan di Umbraton tampak sangat unik!",
  ui_story_5010_50100301_2_dialog_content = "Tapi, entah kenapa rasanya jauh lebih pengap di kota.",
  ui_story_5010_50100301_3_dialog_content = "Menjengkelkan sekali... Orang-orang bilang hujan akan turun, tapi sampai sekarang belum ada rintik hujan setetes pun.",
  ui_story_5010_50100301_4_dialog_content = "Ah...!",
  ui_story_5010_50100301_5_dialog_content = "Lihat lihat! Turnamen baru akan segera dimulai!",
  ui_story_5010_50100301_6_dialog_content = "Hah? Selebaran...?",
  ui_story_5010_50100301_7_dialog_content = "Coba kulihat... Ah, ini untuk Underground Arena.",
  ui_story_5010_50100301_8_dialog_content = "Underground Arena...?",
  ui_story_5010_50100301_9_dialog_content = "Ini pertarungan rahasia, maka dianggap sebagai pertarungan bawah tanah. Seperti lelang yang tadi kausebutkan itu.",
  ui_story_5010_50100301_10_dialog_content = "Aturan untuk pertarungan yang tak terkatakan ini sederhana. Kalahkan lawan Anda menggunakan segala cara yang diperlukan, dan Anda menang.",
  ui_story_5010_50100301_11_dialog_content = "Kalaupun kau tak sengaja membunuh lawanmu... Bukan masalah, kau tak akan dituntut.",
  ui_story_5010_50100301_12_dialog_content = "Wow... Tapi kedengarannya sangat brutal. Bagaimana...",
  ui_story_5010_50100301_13_dialog_content = "Yah, memang pertarungan seperti ini ilegal... Tapi, ini kan Umbraton.",
  ui_story_5010_50100301_14_dialog_content = "Jadi... semua orang bersedia mempertaruhkan hidup mereka untuk hadiahnya?",
  ui_story_5010_50100301_15_dialog_content = "Tidak, tidak juga. Bagi petarung sejati, pertarungan bawah tanah seperti ini adalah arena latihan yang sempurna...",
  ui_story_5010_50100301_16_dialog_content = "Bangunan itu adalah Lin Guild Hall, PlayerName.",
  ui_story_5010_50100301_17_dialog_content = "Apakah ini salah satu toko mereka? Terlihat istimewa, itu sudah pasti.",
  ui_story_5010_50100301_18_dialog_content = "Memang. Sama seperti produk mereka, toko-toko ini juga mencerminkan keindahan karya mereka.",
  ui_story_5010_50100301_19_dialog_content = "Hanya ada penjaga yang berjaga di pintu masuk, serta pemberitahuan yang mengatakan bahwa toko tutup hari ini.",
  ui_story_5010_50100301_20_dialog_content = "Ah... Sayang sekali... Sepertinya aku harus menunggu lain kali untuk melihatnya.",
  ui_story_5010_50100301_21_dialog_content = "Nah, kalau sudah tak ada keperluan di sini, silakan ikut aku ke markas kami, PlayerName.",
  ui_story_5010_50100301_22_dialog_content = "... Baiklah.",
  ui_story_5010_50100301_23_dialog_content = "Ah... Sepertinya hari ini Truth telah menuntunku kepadamu, Luke.",
  ui_story_5010_50100301_24_dialog_content = "Oh, rupanya kau... Berarti semuanya berjalan lancar, ya?",
  ui_story_5010_50100301_25_dialog_content = "Tentu saja...",
  ui_story_5010_50100301_26_dialog_content = "Tu-tunggu, kalian berdua saling kenal?",
  ui_story_5010_50100301_27_dialog_content = "Lama tak jumpa, PlayerName. Menurutku, perjumpaan kita ini adalah tanda restu dari Truth...",
  ui_story_5010_50100301_28_dialog_content = "Tapi, Umbraton sama sekali bukan tempat yang sederhana. Kuharap kau selalu waspada terhadap mara bahaya di sekitarmu... Baik yang tampak maupun yang tak tampak.",
  ui_story_5010_50100301_29_dialog_content = "Apakah Anda berhenti berbicara dalam teka-teki? Bagaimana saya bisa waspada terhadap hal-hal yang tidak bisa saya lihat?",
  ui_story_5010_50100301_30_dialog_content = "Jangan khawatir soal itu. Ada aku yang mendampingimu, begitu pula Bethel.",
  ui_story_5010_50100301_31_dialog_content = "Benar. Kujamin kau akan aman dalam pengawasanku, PlayerName.",
  ui_story_5010_50100301_32_dialog_content = "Ah, ya, aku jadi tenang setelah mendengarnya.",
  ui_story_5010_50100301_33_dialog_content = "Sampai jumpa lagi, PlayerName.",
  ui_story_5010_50100301_34_dialog_content = "Apa yang diberikan Faust kepadamu, Luke?",
  ui_story_5010_50100301_35_dialog_content = "Hmm... Bisa dibilang kejutan. Tak lama lagi kau akan tahu.",
  ui_story_5010_50100301_36_dialog_content = "... Kuharap ini membuat kalian senang.",
  ui_story_5010_50100301_37_dialog_content = "Akhirnya kita sampai. Selamat datang di Markas Besar Umbraton Guild.",
  ui_story_5010_50100301_38_dialog_content = "Ini sama sekali tak tampak seperti Guild... Justru tampak seperti benteng! Pantas saja Luke bilang orang-orang tak mau mencari gara-gara di sekitar sini...",
  ui_story_5010_50100301_39_dialog_content = "Lady Bethel...",
  ui_story_5010_50100301_40_dialog_content = "Selamat siang. Ada kabar dari Shadowlord?",
  ui_story_5010_50100301_41_dialog_content = "Belum, Nona.",
  ui_story_5010_50100301_42_dialog_content = "Aku akan pergi membawa bahan-bahan yang diperlukan. Silakan tunggu beberapa saat.",
  ui_story_5010_50100301_43_dialog_content = "Baiklah, Nona. Silakan, lewat sini.",
  ui_story_5010_50100301_44_dialog_content = "(B-Semua orang sangat sopan di sini! Bagaimana saya harus bereaksi?)",
  ui_story_5010_50100301_45_dialog_content = "... Kau tak perlu membungkuk, PlayerName.",
  ui_story_5010_50100301_46_dialog_content = "Tempat ini membuatku gugup.",
  ui_story_5010_50100301_47_dialog_content = "Aku akan menunggumu di luar.",
  ui_story_5010_50100301_48_dialog_content = "Saya minta maaf untuk menunggu, PlayerName. Berikut adalah buku besar aset, serta dokumentasi yang relevan. Silakan baca selama yang Anda inginkan.",
  ui_story_5010_50100301_49_dialog_content = "Ke mana perginya Luke?",
  ui_story_5010_50100301_50_dialog_content = "Dia baru saja keluar... Ya ampun! Dokumennya banyak sekali!",
  ui_story_5010_50100301_51_dialog_content = "Maafkan aku. Prosesnya memang agak rumit. Aku akan berusaha semampuku untuk menyederhanakannya, tapi tetap ada beberapa dokumen yang harus kautandatangani.",
  ui_story_5010_50100301_52_dialog_content = "Misalnya ini. Lalu ini. Dan ini...",
  ui_story_5010_50100301_53_dialog_content = "Apa perlu kujelaskan tentang dokumen-dokumen ini?",
  ui_story_5010_50100301_54_dialog_content = "G-Graaah...!",
  ui_story_5010_50100301_55_dialog_content = "Ahh! Di-di-dia baru saja berubah menjadi...",
  ui_story_5010_50100301_56_dialog_content = "PlayerName! Ada satu Eclipsite di pintu masuk utama!",
  ui_story_5010_50100301_57_dialog_content = "?!",
  ui_story_5010_50100301_58_dialog_content = "Kok bisa tiba-tiba ada Eclipsite muncul di sini?!",
  ui_story_5010_50100301_59_dialog_content = "Prioritas utama kita adalah mengevakuasi warga sipil! Tutup gerbang utama dan kawal semua orang keluar dari belakang!",
  ui_story_5010_50100301_60_dialog_content = "Paham!",
  ui_story_5010_50100301_61_dialog_content = "Anda punya nyali... Membuat masalah di depan Persekutuan!",
  ui_story_5010_50100301_62_dialog_content = "Masih ada lagi!",
  ui_story_5010_50100301_63_dialog_content = "Lawan, Frankel!",
  ui_story_5010_50100301_64_dialog_content = "Berlindunglah di belakangku, PlayerName!",
  ui_story_5010_50100401_1_dialog_content = "Lady Bethel!",
  ui_story_5010_50100401_2_dialog_content = "Apa kau... Oh, syukurlah kau baik-baik saja, Nona!",
  ui_story_5010_50100401_3_dialog_content = "Mana para penjaga? Kenapa hanya ada sedikit sekali orang di sini?",
  ui_story_5010_50100401_4_dialog_content = "J-Jangan khawatir, Nona Bethel! Saya akan menemukan lebih banyak bantuan! Serahkan ini padaku!",
  ui_story_5010_50100401_5_dialog_content = "Apa itu anak buahmu, Bethel?",
  ui_story_5010_50100401_6_dialog_content = "Ya, memangnya kenapa?",
  ui_story_5010_50100401_7_dialog_content = "Sepertinya mereka tak punya pengalaman tempur. Lihat saja, mereka ketakutan setengah mati.",
  ui_story_5010_50100401_8_dialog_content = "Hmmm...",
  ui_story_5010_50100401_9_dialog_content = "Tunggu!",
  ui_story_5010_50100401_10_dialog_content = "Apa kau menemukan sesuatu?",
  ui_story_5010_50100401_11_dialog_content = "Pojokan itu! Ada sesuatu di sana!",
  ui_story_5010_50100401_12_dialog_content = "... Frankel, coba lihat ada apa di depan sana.",
  ui_story_5010_50100401_13_dialog_content = "Guk!",
  ui_story_5010_50100401_14_dialog_content = "Graagh!",
  ui_story_5010_50100401_15_dialog_content = "Guk! Guk!",
  ui_story_5010_50100401_16_dialog_content = "Cepat, 'kan?",
  ui_story_5010_50100401_17_dialog_content = "Graaaaaah!!",
  ui_story_5010_50100401_18_dialog_content = "Dasar, dungu semuanya. Cuma dengan Frankel maju saja, mereka sudah terpancing keluar.",
  ui_story_5010_50100401_19_dialog_content = "Terima kasih atas peringatannya, PlayerName. Anda sangat perseptif.",
  ui_story_5010_50100401_20_dialog_content = "Apakah Anda yakin ini adalah penyergapan? Saya masih merasakan banyak dari mereka di dekatnya! Tetap waspada...",
  ui_story_5010_50100401_21_dialog_content = "Terimalah hukumanmu!",
  ui_story_5010_50100401_22_dialog_content = "Graaaugh...!",
  ui_story_5010_50100401_23_dialog_content = "<color=#FFB400>Pittman</color>!",
  ui_story_5010_50100401_24_dialog_content = "Lumopolis... Kenapa mereka memutuskan mengutus orang dari Hall of Justice kemari?",
  ui_story_5010_50100401_25_dialog_content = "Bau makhluk ini... Berkat bau itu, akhirnya aku bisa menemukan tempat ini.",
  ui_story_5010_50100401_26_dialog_content = "Itu Wayne Pittman, penyelidik dari Hall of Justice. Kami pernah bertempur berdampingan, Betel.",
  ui_story_5010_50100401_27_dialog_content = "Salam, Pittman dari Lumopolis. Aku Bethel, kepala Umbraton Guild.",
  ui_story_5010_50100401_28_dialog_content = "Apakah Anda mencari sesuatu di sini di Umbraton? Jika Anda sedang mencari jalan kembali ke Lumopolis, saya akan dengan senang hati menunjukkannya kepada Anda.",
  ui_story_5010_50100401_29_dialog_content = "... Tenanglah, aku kemari bukan dengan niat buruk. Penyelidikan yang sedang kulakukan sama sekali tak ada hubungannya dengan kalian.",
  ui_story_5010_50100401_30_dialog_content = "Para Eclipsite yang tadi itu... Apa kalian lihat bagaimana tepatnya mereka bisa muncul di sini?",
  ui_story_5010_50100401_31_dialog_content = "Itu sangat mendadak, dan para penjaga tidak dapat merespons tepat waktu. Eclipsites ini lebih kuat dari biasanya, dan tampaknya cukup akrab dengan markas.",
  ui_story_5010_50100401_32_dialog_content = "Saya berdiri di luar. Saya benar-benar melihat orang biasa tiba-tiba berubah menjadi satu ...",
  ui_story_5010_50100401_33_dialog_content = "Hmm... Persis seperti dugaanku.",
  ui_story_5010_50100401_34_dialog_content = "<color=#FFB400>Enhancer</color>.",
  ui_story_5010_50100401_35_dialog_content = "Maaf, En-apa?",
  ui_story_5010_50100401_36_dialog_content = "Saat para Eclipsite itu muncul, apa ada di antara mereka yang menunjukkan perilaku aneh atau kacau?",
  ui_story_5010_50100401_37_dialog_content = "Aku tak terlalu memperhatikan, sih. Bagaimana denganmu, Bethel?",
  ui_story_5010_50100401_38_dialog_content = "Sebentar, Frankel merasakan ada sesuatu...",
  ui_story_5010_50100401_39_dialog_content = "Graaaaaaagh!!",
  ui_story_5010_50100401_40_dialog_content = "Sayang sekali... Lagi-lagi aku melewatkan kesempatan untuk melihatnya memanfaatkan Enhancer.",
  ui_story_5010_50100401_41_dialog_content = "Kalau kita membelahnya, mungkin kita masih bisa menemukan sesuatu, ya?",
  ui_story_5010_50100401_42_dialog_content = "Luke, kau tak berniat membantu, nih?",
  ui_story_5010_50100401_43_dialog_content = "Tugasku adalah melindungimu, bukan membantu perwira Lumopolis atau berperang.",
  ui_story_5010_50100402_1_dialog_content = "Terima kasih atas bantuanmu, Pittman.",
  ui_story_5010_50100402_2_dialog_content = "Tapi, sebenarnya bagaimana mereka melakukannya? Bagaimana kecepatan dan kekuatan mereka bisa tiba-tiba meningkat seperti itu?",
  ui_story_5010_50100402_3_dialog_content = "Benda yang kami sebut Enhancer. Itu obat kuat yang memberikan kekuatan Eclipsite kepada Aurorian walau hanya sebentar.",
  ui_story_5010_50100402_4_dialog_content = "Tapi, yang lebih mengkhawatirkan adalah bahwa siapa pun yang menelan Enhancer itu akan berubah menjadi Eclipsite.",
  ui_story_5010_50100402_5_dialog_content = "Pantas saja orang-orang yang menunggu untuk menyergap kita tadi itu tak bisa mengendalikan diri saat Frankel melintasi mereka... Sepertinya mereka tak punya waktu untuk bersabar.",
  ui_story_5010_50100402_6_dialog_content = "Artinya, kalau saja tadi kitalah yang berjalan melintasi mereka... Kita pasti sudah terkena masalah besar.",
  ui_story_5010_50100402_7_dialog_content = "Fyuh, nyaris saja... Aku sudah kembali, Lady Bethel! Sepertinya semua Eclipsite itu sudah diberantas...",
  ui_story_5010_50100402_8_dialog_content = "Lady Bethel! Kami sudah di sini!",
  ui_story_5010_50100402_9_dialog_content = "Kalian semua, jaga tempat ini! Seth!",
  ui_story_5010_50100402_10_dialog_content = "Ya, Nona!",
  ui_story_5010_50100402_11_dialog_content = "Temui Shadowlord dan minta penjaga lebih banyak!",
  ui_story_5010_50100402_12_dialog_content = "Paham!",
  ui_story_5010_50100402_13_dialog_content = "Menggunakan Enhancer untuk bertransformasi dan meningkatkan kekuatan tempur untuk sementara waktu... Apa ini terdengar familier untukmu, PlayerName?",
  ui_story_5010_50100402_14_dialog_content = "Jangan-jangan...?",
  ui_story_5010_50100402_15_dialog_content = "Benar. Sejak perpisahan kita di Eraveil, aku terus melakukan penyelidikan tentang transformasi ini...",
  ui_story_5010_50100402_16_dialog_content = "Dan, pada akhirnya, penyelidikanku mengarahkanku kemari, ke Umbraton...",
  ui_story_5010_50100402_17_dialog_content = "Seperti berdiri, efek penambah ini sangat mirip dengan modifikasi aneh yang kita temui sebelumnya. Oleh karena itu, kemungkinan besar mereka memiliki asal yang sama.",
  ui_story_5010_50100402_18_dialog_content = "Mungkinkah asal usul seni gelap dan bengkok ini terletak di Umbraton?",
  ui_story_5010_50100402_19_dialog_content = "Kurasa Enhancer itu tidak berasal dari Umbraton, Pittman. Akulah yang bertanggung jawab atas Umbraton Guild, dan aku belum pernah mendengar tentangnya!",
  ui_story_5010_50100402_20_dialog_content = "Setuju. Aku belum pernah dengar apa pun tentang hal itu.",
  ui_story_5010_50100402_21_dialog_content = "Lagi pula, Eclipsite memang cukup sering menyerang wilayah sekitar sini. Ini Umbraton, bukan firdaus nyaman di langit.",
  ui_story_5010_50100402_22_dialog_content = "Yang jelas, aku bersyukur kau tak terluka, PlayerName. Kalau sampai kau kenapa-kenapa, aku tak akan bisa menjelaskannya kepada Shadowlord.",
  ui_story_5010_50100402_23_dialog_content = "Shadowlord... Shadowlord... Ya, aku jadi ingat.",
  ui_story_5010_50100402_24_dialog_content = "Maksudmu apa sih, Pittman?",
  ui_story_5010_50100402_25_dialog_content = "Yang benar-benar paham tentang peristiwa yang terjadi di Umbraton hanyalah Shadowlord sendiri. Aku harus menemuinya.",
  ui_story_5010_50100402_26_dialog_content = "Aku akan melapor kepada Istvan dan menunggu perintah darinya.",
  ui_story_5010_50100402_27_dialog_content = "Apa yang membuatmu begitu yakin bahwa Umbraton-lah sumber masalahmu, Pittman?",
  ui_story_5010_50100402_28_dialog_content = "Tenangkan dirimu, Luke... Dia juga punya pekerjaan yang harus dituntaskan...",
  ui_story_5010_50100402_29_dialog_content = "Mari kita luruskan daripada bertengkar di sini.",
  ui_story_5010_50100402_30_dialog_content = "Sekarang kita punya musuh yang bisa berubah menjadi Eclipsite, tapi jumlah dan niat mereka masih belum ketahuan.",
  ui_story_5010_50100402_31_dialog_content = "Dengan situasi kita sekarang, PlayerName... kurasa kita terpaksa menunda urusan kita tadi. Apa kau tak keberatan?",
  ui_story_5010_50100402_32_dialog_content = "Sebenarnya, mungkin akan jauh lebih mudah kalau kutinggalkan saja aset itu di sini daripada kubawa ke mana-mana.",
  ui_story_5010_50100402_33_dialog_content = "Setuju. Aku akan memeriksa ke stasiun untuk memastikan apakah ada orang-orang aneh yang muncul di kota belakangan ini.",
  ui_story_5010_50100402_34_dialog_content = "Stasiun?",
  ui_story_5010_50100402_35_dialog_content = "Ini adalah tempat untuk mencari informasi di sekitar sini.",
  ui_story_5010_50100402_36_dialog_content = "Kurasa tempatnya juga tidak terlalu jauh dari sini... Bagaimana kalau kau ikut denganku saja, PlayerName? Toh aku kan tak bisa meninggalkanmu sendirian.",
  ui_story_5010_50100402_37_dialog_content = "Maaf, apa kira-kira aku bisa bertanya-tanya tentang Enhancer di stasiunmu itu?",
  ui_story_5010_50100402_38_dialog_content = "Mungkin, tapi aku juga tak yakin. Tak ada salahnya dicoba.",
  ui_story_5010_50100402_39_dialog_content = "Ada sebuah persimpangan di tengah kota, di mana mereka menggantungkan lampu biru di jalanan. Tempat yang akan kita tuju adalah sebuah bar di sudut jalan, bernama The Crossroads.",
  ui_story_5010_50100402_40_dialog_content = "Seberapa pas...",
  ui_story_5010_50100402_41_dialog_content = "Pengunjung bar itu berasal dari beragam latar belakang, jadi pastikan kau sudah siap sebelum kita masuk ke sana.",
  ui_story_5010_50100402_42_dialog_content = "Saya ragu mereka bisa lebih buruk daripada Eclipsites yang ditingkatkan yang kita lawan hari ini.",
  ui_story_5010_50100402_43_dialog_content = "Kami hanya ingin tahu siapa yang memberikan Enhancer itu. Kurasa tak akan ada Eclipsite berkeliaran di bar.",
  ui_story_5010_50100402_44_dialog_content = "Saya akan melindungi PlayerName. Jangan ragu untuk menyelidikinya, Tn. Pittman... sendirian.",
  ui_story_5010_50100402_45_dialog_content = "Persimpangan dengan lampu biru... Aneh, aku tidak ingat pernah melihat tempat seperti itu sebelumnya?",
  ui_story_5010_50100402_46_dialog_content = "Itu hanya ada selama beberapa tahun. Mungkin Anda masih belajar di luar negeri saat dibuka?",
  ui_story_5010_50100402_47_dialog_content = "Kalau begitu kita bisa pergi bersama. Mungkin kita akan belajar lebih banyak tentang siapa yang melancarkan serangan ke Persekutuan.",
  ui_story_5010_50100402_48_dialog_content = "Eee... Baiklah, sesukamu saja, Bethel. Tapi, tolong, setelah kita sampai di sana...",
  ui_story_5010_50100402_49_dialog_content = "Jaga perkataan dan perbuatanmu di dalam sana.",
  ui_story_5010_50100501_1_dialog_content = "The Crossroads bisa jadi tempat yang rumit, jadi sebaiknya semua orang tidak bicara sembarangan.",
  ui_story_5010_50100501_2_dialog_content = "Bukan masalah.",
  ui_story_5010_50100501_3_dialog_content = "Bar di sana itu sepi sekali... Barnya buka tidak, sih?",
  ui_story_5010_50100501_4_dialog_content = "Lampu biru menyala, jadi seharusnya begitu. Ini aneh, meskipun... Biasanya, Anda dapat mendengar keributan setidaknya dari tiga blok jauhnya...",
  ui_story_5010_50100501_5_dialog_content = "Apa pun itu, yang penting kita harus tetap waspada setelah masuk ke sana.",
  ui_story_5010_50100501_6_dialog_content = "Pintunya memang terbuka... Pelayan! Pelayan!!",
  ui_story_5010_50100501_X6_dialog_content = "Permisi!",
  ui_story_5010_50100501_7_dialog_content = "Bethel, kau seharusnya memesan dari bar...",
  ui_story_5010_50100501_8_dialog_content = "...",
  ui_story_5010_50100501_9_dialog_content = "Apa yang kamu lihat?!",
  ui_story_5010_50100501_10_dialog_content = "Woah!",
  ui_story_5010_50100501_11_dialog_content = "PlayerName! Kemarilah!",
  ui_story_5010_50100501_12_dialog_content = "Kau, uh... Mungkin ingin menjaga jarak dari mereka. Tunggu aku di sini, oke?",
  ui_story_5010_50100501_13_dialog_content = "Baiklah... Kami akan ikuti perintahmu.",
  ui_story_5010_50100501_14_dialog_content = "Selamat malam.",
  ui_story_5010_50100501_15_dialog_content = "...",
  ui_story_5010_50100501_16_dialog_content = "Saya Pittman, seorang penyelidik dari Lumopolis.",
  ui_story_5010_50100501_17_dialog_content = "Aku ingin bertanya sedikit kepada kalian semua. Aku akan sangat berterima kasih kalau kalian mau bekerja sama.",
  ui_story_5010_50100501_18_dialog_content = "?!?!",
  ui_story_5010_50100501_19_dialog_content = "W-Wayne! Kau tak boleh tiba-tiba bertanya seenaknya seperti itu!!",
  ui_story_5010_50100501_20_dialog_content = "...",
  ui_story_5010_50100501_21_dialog_content = "...",
  ui_story_5010_50100501_22_dialog_content = "Hwaa! Se-sejak kapan mereka sudah sedekat itu dengan kita?!",
  ui_story_5010_50100501_23_dialog_content = "Apa-apaan ini, sedang apa kau? Kembali kemari, PlayerName!",
  ui_story_5010_50100501_24_dialog_content = "Apa yang kautakutkan, Nak? Aku tak akan memakanmu, kok.",
  ui_story_5010_50100501_25_dialog_content = "Bos kami ingin bicara sebentar dengan kalian berdua. Kalian tak keberatan duduk berbincang dengannya, 'kan?",
  ui_story_5010_50100501_26_dialog_content = "...",
  ui_story_5010_50100501_27_dialog_content = "...",
  ui_story_5010_50100501_28_dialog_content = "Lama tak jumpa, Rhein.",
  ui_story_5010_50100501_29_dialog_content = "Lady Bethel... Hari yang lamban di tempat kerja, kurasa?",
  ui_story_5010_50100501_30_dialog_content = "Gara-gara insiden di markas besar kita tadi, tak ada pekerjaan yang harus kutangani hari ini. Kau sendiri...",
  ui_story_5010_50100501_31_dialog_content = "Bagaimana kondisi bisnis <color=#FFB400>Blue Lion Guild</color> akhir-akhir ini?",
  ui_story_5010_50100501_32_dialog_content = "Hahaha, tahu sendirilah, biasa saja! Tak ada yang istimewa!",
  ui_story_5010_50100501_33_dialog_content = "Tidak perlu terlalu tegang! Kami hanya mengobrol, itu saja!",
  ui_story_5010_50100501_34_dialog_content = "Lalu mari kita mulai. Apa sebenarnya yang ingin Anda bicarakan?",
  ui_story_5010_50100501_35_dialog_content = "Apakah itu tentang enhancer, atau serangan terhadap Guild kita hari ini?",
  ui_story_5010_50100501_36_dialog_content = "Saya tidak tertarik untuk mengobrol tentang hal lain.",
  ui_story_5010_50100501_37_dialog_content = "Apa-apaan ini? Minum-minum sambil mengobrol dengan kepala Blue Lion Guild dan aku tak diundang? Rasanya hatiku sakit sekali, tahu!",
  ui_story_5010_50100501_38_dialog_content = "Seorang tentara bayaran dari White Flame, seorang penyelidik dari Hall of Justice, kepala Umbraton Guild, dan...",
  ui_story_5010_50100501_39_dialog_content = "...Seorang bocah lemah yang tak bisa menggunakan Luminatics apa pun.",
  ui_story_5010_50100501_40_dialog_content = "Rupanya anggota timmu sangat beragam, Lady Bethel.",
  ui_story_5010_50100501_41_dialog_content = "Tapi, nyatanya tadi kami berhasil menumpas satu legiun Eclipsite, lho...",
  ui_story_5010_50100501_42_dialog_content = "Memang.",
  ui_story_5010_50100501_43_dialog_content = "Maaf, tapi aku tidak berbicara denganmu, Luke. Kepala geng anjing tentara bayaran yang mati masih tetap seekor anjing, jadi mengapa Anda tidak mengunyah tulang dan membiarkan kami yang berbicara?",
  ui_story_5010_50100501_44_dialog_content = "!!",
  ui_story_5010_50100501_45_dialog_content = "Rhein...!",
  ui_story_5010_50100501_46_dialog_content = "Kami di sini untuk mencari informasi, bukan untuk melawan. Jika Anda tidak punya apa-apa untuk diberikan, saya yakin ada banyak orang yang bisa kita ajak bicara.",
  ui_story_5010_50100501_47_dialog_content = "Aku tak punya. Aku tak mendengar informasi apa pun sepanjang malam.",
  ui_story_5010_50100501_48_dialog_content = "Dalam hal ini, obrolan ini berakhir di sini.",
  ui_story_5010_50100501_49_dialog_content = "Ayo, Nona Bethel.",
  ui_story_5010_50100501_50_dialog_content = "...",
  ui_story_5010_50100501_51_dialog_content = "Dia bahkan sama sekali tak mau melirik penyelidik dari Lumopolis... Orang-orang Umbraton benar-benar tak takut hukum, ya?",
  ui_story_5010_50100501_52_dialog_content = "Yah, Blue Lion Guild memang berkuasa. Belakangan ini mereka berhasil mengumpulkan banyak sekali uang dan pengikut...",
  ui_story_5010_50100501_53_dialog_content = "Tapi, tanpa Markas Guild, bisnis mereka tak akan berjaya. Semua rute dagang kan ada di bawah kendali kami.",
  ui_story_5010_50100501_54_dialog_content = "...",
  ui_story_5010_50100501_55_dialog_content = "Apakah kamu baik-baik saja, Lukas?",
  ui_story_5010_50100501_56_dialog_content = "Dari dulu Rhein memang tak terlalu suka dengan tentara bayaran, tapi kuasa Blue Lion Guild sekarang sudah sangat besar... Kami hanya bisa menyengir dan memakluminya.",
  ui_story_5010_50100501_57_dialog_content = "Kudengar dia membuka beberapa rute dagang tak resmi yang baru untuk dirinya sendiri, dan mereka berhasil meraup untung karenanya.",
  ui_story_5010_50100501_58_dialog_content = "Soal apa yang sebenarnya mereka jual, belum ada laporan apa pun ke Markas Guild tentang itu...",
  ui_story_5010_50100501_59_dialog_content = "Apa?",
  ui_story_5010_50100501_60_dialog_content = "Tampaknya penyelidikan yang tepat di Blue Lion Guild sudah beres.",
  ui_story_5010_50100501_61_dialog_content = "!!",
  ui_story_5010_50100501_62_dialog_content = "Seth? Ada apa?",
  ui_story_5010_50100501_63_dialog_content = "Shadow... Baru saja... Ketemu!",
  ui_story_5010_50100501_64_dialog_content = "Kau ini mau bilang apa, sih? Tenangkan dirimu!",
  ui_story_5010_50100501_65_dialog_content = "Shadowlord! Dia... Dia diserang...!",
  ui_story_5010_50100501_66_dialog_content = "...",
  ui_story_5010_50100501_67_dialog_content = "!!!",
  ui_story_5010_50100501_68_dialog_content = "Bethel? Apa yang terjadi?",
  ui_story_5010_50100501_69_dialog_content = "Guk! Guk, guk!!",
  ui_story_5010_50100501_70_dialog_content = "Tunggu... Siapa itu di depan?",
  ui_story_5010_50100501_71_dialog_content = "Awas, PlayerName!!",
  ui_story_5010_50100501_72_dialog_content = "Bwahahahaha!",
  ui_story_5010_50100501_73_dialog_content = "Lagi-lagi bau familier itu...",
  ui_story_5010_50100501_74_dialog_content = "<color=#FFB400>Pil</color> itu... Jangan bilang...!",
  ui_story_5010_50100501_75_dialog_content = "Itu... Itu benar! Graahaha!",
  ui_story_5010_50100501_76_dialog_content = "Dia... Dia berubah menjadi Eclipsite!!!",
  ui_story_5010_50100501_77_dialog_content = "Bethel!",
  ui_story_5010_50100501_78_dialog_content = "Shadowlord tak bisa dihubungi! Sepertinya dia juga sedang diserang!",
  ui_story_5010_50100501_79_dialog_content = "Musuh menyerang! Bersiap untuk bertempur! ...Hei, dengar, tidak?!",
  ui_story_5010_50100501_80_dialog_content = "... Drat. Aku juga tidak bisa menghubungi Seth.",
  ui_story_5010_50100501_81_dialog_content = "Wayne, kita berdua tahan mereka!",
  ui_story_5010_50100501_82_dialog_content = "Memangnya mungkin menangkapnya hidup-hidup?",
  ui_story_5010_50100502_1_dialog_content = "Para Eclipsite ini... Bukan, mereka orang-orang Umbraton yang tampak seperti Eclipsite. Itukah efek pil itu terhadap mereka...?",
  ui_story_5010_50100502_2_dialog_content = "Pernahkah Anda semua melihat transformasi dengan jelas? Mereka berubah menjadi makhluk yang lebih kuat dari Eclipsites biasa.",
  ui_story_5010_50100502_3_dialog_content = "Inikah \"transformasi\" yang tadi kausebut itu?",
  ui_story_5010_50100502_4_dialog_content = "Pendek kata, ini memang semacam \"transformasi\".",
  ui_story_5010_50100502_5_dialog_content = "Kau yakin tak tahu apa-apa lagi tentang \"Enhancer\" ini? Apa dulu Umbraton memang belum pernah menghadapi bahaya semacam ini?",
  ui_story_5010_50100502_6_dialog_content = "Setahuku memang belum pernah. Ini pasti baru terjadi belakangan ini. Kalau tidak, seluruh kota pastinya sekarang sudah panik.",
  ui_story_5010_50100502_7_dialog_content = "Sekarang pun, aku masih tak bisa memercayainya. Ada orang yang bisa begitu saja berubah menjadi Eclipsite...",
  ui_story_5010_50100502_8_dialog_content = "Tampaknya Blue Lion Guild entah bagaimana terhubung dengan semua ini.",
  ui_story_5010_50100502_9_dialog_content = "Ya, aku setuju. Tak mungkin ini hanya kebetulan.",
  ui_story_5010_50100502_10_dialog_content = "Sayangnya, saya tidak dapat memastikan apa pun tentang identitas orang-orang ini dalam keadaan transformasi mereka. Mereka juga tidak meninggalkan petunjuk...",
  ui_story_5010_50100502_11_dialog_content = "Untuk sekarang ini, aku akan melanjutkan penyelidikanku dari sini dan memantau pergerakan Rhein.",
  ui_story_5010_50100502_12_dialog_content = "Eh... Mana Bethel?",
  ui_story_5010_50100502_13_dialog_content = "Bethel! Kau di mana?",
  ui_story_5010_50100502_14_dialog_content = "Situasi Shadowlord masih belum jelas; yang kutahu hanyalah dia diserang.",
  ui_story_5010_50100502_15_dialog_content = "Aku harus mencarinya.",
  ui_story_5010_50100502_16_dialog_content = "Kau baik-baik saja?",
  ui_story_5010_50100502_17_dialog_content = "Maafkan aku, PlayerName... Urusan warisanmu terpaksa tertunda lagi. Kita bahas lagi nanti setelah aku kembali.",
  ui_story_5010_50100502_18_dialog_content = "Maafkan aku.",
  ui_story_5010_50100502_19_dialog_content = "Hah? Memangnya Shadowlord kenapa? Mungkinkah ini ulah Blue Lion Guild...?",
  ui_story_5010_50100502_20_dialog_content = "Saya tidak yakin, tapi kami akan menangani urusan kami sendiri, terima kasih.",
  ui_story_5010_50100502_21_dialog_content = "...",
  ui_story_5010_50100502_22_dialog_content = "Jadi, apa rencana kita sekarang, PlayerName?",
  ui_story_5010_50100502_23_dialog_content = "Saat ini, sepertinya kita tak bisa berbuat banyak untuk membantu mereka.",
  ui_story_5010_50100502_24_dialog_content = "Oh, iya! Masih ada lelang bawah tanah itu!",
  ui_story_5010_50100502_25_dialog_content = "Oh, iya, aku jadi ingat... Sebenarnya apa yang kaucari di lelang itu?",
  ui_story_5010_50100502_26_dialog_content = "Set komponen untuk ruang simulasi. Naroxel memberitahuku soal komponen itu.",
  ui_story_5010_50100502_27_dialog_content = "Komponen itu sangat penting untuk Colossus, dan mungkin bisa berguna untuk Soroz.",
  ui_story_5010_50100502_28_dialog_content = "Aku paham. Kalau begitu, setelah sampai di sana, lakukan persis seperti yang kubilang.",
  ui_story_5010_50100502_29_dialog_content = "Jangan sampai ada insiden lagi hari ini!",
  ui_story_5010_50100601_1_dialog_content = "Kita sudah hampir sampai, PlayerName.",
  ui_story_5010_50100601_2_dialog_content = "Luke... A-apa yang harus kulakukan? Apa sebaiknya aku bicara dengan juru lelang?",
  ui_story_5010_50100601_3_dialog_content = "Jangan! Semua peserta dalam lelang bawah tanah ini menggunakan identitas samaran. Agar bisa masuk ke sana, kau harus menghubungi pihak penyelenggaranya.",
  ui_story_5010_50100601_4_dialog_content = "Begini prosedurnya: penjual memberikan barangnya kepada penyelenggara, lalu para pembeli dan penyelenggara...",
  ui_story_5010_50100601_5_dialog_content = "Baiklah, baiklah, aku paham. Kita harus menghubungi pihak penyelenggara dan mengajukan penawaran. Begitu, 'kan?",
  ui_story_5010_50100601_6_dialog_content = "Tak segampang itu! Penyelenggara akan menjadwalkan lelang anonim pada tanggal tertentu, dan barang akan terjual kepada penawar tertinggi.",
  ui_story_5010_50100601_7_dialog_content = "Pada tanggal tertentu? Jadi, kita harus menunggu sampai lelangnya diadakan...",
  ui_story_5010_50100601_8_dialog_content = "Tidak persis. Kita bisa mencari penyelenggara untuk mendapatkan beberapa detail dari mereka. Dengan sedikit keberuntungan, kita bahkan mungkin bisa melihat barangnya...",
  ui_story_5010_50100601_9_dialog_content = "Aku paham. Kalau begitu, intinya adalah kita hadir dalam proses lelang dan mengajukan penawaran tertinggi, 'kan?",
  ui_story_5010_50100601_10_dialog_content = "PlayerName, tadi kan sudah kubilang, pembeli di lelang ini harus merahasiakan identitas mereka... Jadi, kalau kau ingin menawar sesuatu, prosesnya agak lebih rumit.",
  ui_story_5010_50100601_11_dialog_content = "\"Merahasiakan identitas\"? Bahkan para pembelinya?",
  ui_story_5010_50100601_12_dialog_content = "Tentu saja! Kalau kau berhasil membeli barang berharga dan semua orang tahu identitasmu, sama saja artinya kau mengundang orang untuk merampokmu... Atau lebih parah lagi.",
  ui_story_5010_50100601_13_dialog_content = "Sudahlah, bisa berjam-jam kalau harus kujelaskan semuanya. Sebaiknya kita lihat-lihat saja dulu.",
  ui_story_5010_50100601_14_dialog_content = "Baiklah, Luke.",
  ui_story_5010_50100601_15_dialog_content = "Ini daftar barang yang akan segera dilelang, beserta tanggal lelangnya. Coba bacalah, PlayerName.",
  ui_story_5010_50100601_16_dialog_content = "Orang yang barusan itu...",
  ui_story_5010_50100601_17_dialog_content = "Tak perlu dipikirkan.",
  ui_story_5010_50100601_18_dialog_content = "Sepertinya mereka tak akan mengadakan lelang untuk \"komponen ruang simulasi\" yang kaucari itu dalam waktu dekat ini. Bagaimana kalau kita tanyakan saja harga awal yang diminta penjualnya?",
  ui_story_5010_50100601_19_dialog_content = "Barang-barang dalam daftar ini... Bagaimana... Bagaimana mungkin orang sampai berpikiran untuk...",
  ui_story_5010_50100601_20_dialog_content = "Ha ha ha ha! Ada alasan mengapa ini adalah lelang bawah tanah, lho!",
  ui_story_5010_50100601_21_dialog_content = "Bagaimana ceritanya sampai mereka bisa menemukan barang-barang semacam ini?",
  ui_story_5010_50100601_22_dialog_content = "Hmm... Itu urusan si penjual, sih, bukan urusan kita. Mungkin saja mereka menggalinya, atau membuatnya sendiri... Mungkin juga barang itu hasil curian.",
  ui_story_5010_50100601_23_dialog_content = "Tunggu... Jadi, tak ada yang meributkan soal asal barang-barang itu?!",
  ui_story_5010_50100601_24_dialog_content = "Hah, bagaimana menurutmu?",
  ui_story_5010_50100601_25_dialog_content = "Dan orang-orang dengan santainya melelang barang yang mungkin saja hasil curian?",
  ui_story_5010_50100601_26_dialog_content = "Yah, lelang ini pastinya punya kredibilitas TERTENTU, 'kan? Lagi pula, lelang ini sudah beroperasi selama bertahun-tahun.",
  ui_story_5010_50100601_27_dialog_content = "Lumayan ramai... Apa semua orang ini kemari untuk melihat barang yang akan dilelang?",
  ui_story_5010_50100601_28_dialog_content = "Jangan berisik!",
  ui_story_5010_50100601_29_dialog_content = "Melihat dari perilaku mereka semua, sepertinya mereka kemari untuk mengajukan penawaran untuk lelang hari ini.",
  ui_story_5010_50100601_30_dialog_content = "Jumlah pengunjungnya berjibun... Aku yakin mereka adalah orang-orang penting di Umbraton.",
  ui_story_5010_50100601_31_dialog_content = "...Hah? Orang-orang di sana itu...",
  ui_story_5010_50100601_32_dialog_content = "Faust? Dan Beryl? ... Bahkan Paloma juga?!",
  ui_story_5010_50100601_33_dialog_content = "Waow... Aku kaget, ternyata kau kenal Faust, PlayerName...",
  ui_story_5010_50100601_34_dialog_content = "Tapi, aku sama sekali tak menyangka, ternyata kau juga kenal dengan nona-nona dari True Order itu juga, ya?",
  ui_story_5010_50100601_35_dialog_content = "Ceritanya panjang, sih...",
  ui_story_5010_50100601_36_dialog_content = "<color=#e8d9bb>Tik-tik-tik...</color>",
  ui_story_5010_50100601_37_dialog_content = "Lho, hujan malah mulai turun...? Ayo, Luke, kita masuk saja!",
  ui_story_5010_50100601_38_dialog_content = "Yah, ayo.",
  ui_story_5010_50100601_39_dialog_content = "Nah, akhirnya hujan...",
  ui_story_5010_50100601_40_dialog_content = "...",
  ui_story_5010_50100601_41_dialog_content = "...",
  ui_story_5010_50100601_42_dialog_content = "...",
  ui_story_5010_50100601_43_dialog_content = "(Sunyi sekali...)",
  ui_story_5010_50100601_44_dialog_content = "Lewat sini, PlayerName. Lelangnya diadakan di sana itu; kita sedang mencari penyelenggaranya. Ingat, 'kan?",
  ui_story_5010_50100601_45_dialog_content = "Omong-omong... Kira-kira, apa kau bisa membedakan apakah komponen itu palsu atau tidak, PlayerName?",
  ui_story_5010_50100601_46_dialog_content = "Pihak penyelenggara bilang, komponen itu sudah diperiksa oleh teknisi dari Illumina dan Rediesel Wrench. Ini sertifikatnya.",
  ui_story_5010_50100601_47_dialog_content = "Eh, yang benar saja...",
  ui_story_5010_50100601_48_dialog_content = "Kedua orang itu temanku, Luke. Komponen itu pasti asli!",
  ui_story_5010_50100601_49_dialog_content = "Baiklah. Kalau begitu, langkah berikutnya adalah mendaftar sebagai calon pembeli dalam lelang mereka.",
  ui_story_5010_50100601_50_dialog_content = "Nah, kau mau bayar berapa untuk komponen itu, PlayerName?",
  ui_story_5010_50100601_51_dialog_content = "...<size=45>678 Nightium?!</size>",
  ui_story_5010_50100601_52_dialog_content = "Anu... Y-yah... Itu sekitar seperseribu dari harga awal yang diminta penjualnya...",
  ui_story_5010_50100601_53_dialog_content = "T-Tapi hanya itu uang yang kumiliki sekarang...",
  ui_story_5010_50100601_54_dialog_content = "Baiklah... Sepertinya kita harus mundur dan memikirkan hal lain saja.",
  ui_story_5010_50100601_55_dialog_content = "Untungnya, lelang untuk komponen ruang simulasi itu belum akan diadakan dalam waktu dekat ini.",
  ui_story_5010_50100601_56_dialog_content = "Baik...",
  ui_story_5010_50100601_57_dialog_content = "Tak perlu terlalu khawatir soal itu. Kalau kita bisa menemukan barang yang cukup berharga, kita mungkin bisa bernegosiasi dengan penjualnya...",
  ui_story_5010_50100601_58_dialog_content = "<size=45><color=#e8d9bb>Dor!</color></size>",
  ui_story_5010_50100601_59_dialog_content = "Suara berisik barusan itu apa?",
  ui_story_5010_50100601_60_dialog_content = "Asalnya dari ruang lelang... Firasatku jadi tak enak.",
  ui_story_5010_50100601_61_dialog_content = "Ayo, mari kita lihat!",
  ui_story_5010_50100601_62_dialog_content = "Tu-tunggu, Pak! Kau tak boleh asal...",
  ui_story_5010_50100601_63_dialog_content = "Tak boleh asal apa? Begini?",
  ui_story_5010_50100601_64_dialog_content = "<size=45><color=#e8d9bb>Dor! Dor!</color></size>",
  ui_story_5010_50100601_65_dialog_content = "Tembakan?!",
  ui_story_5010_50100601_66_dialog_content = "Tiarap! Jangan bergerak...",
  ui_story_5010_50100601_67_dialog_content = "Maaf menyela, kalian semua...",
  ui_story_5010_50100601_68_dialog_content = "Apa-apaan kau ini?!",
  ui_story_5010_50100601_69_dialog_content = "Ssst... Harap tetap diam, jika Anda mau.",
  ui_story_5010_50100601_70_dialog_content = "Kami hanya ingin menyampaikan pengumuman, itu saja. Tak perlu panik...",
  ui_story_5010_50100601_71_dialog_content = "Tolong, Maude, boleh? Sudah lama sekali aku ingin mengucapkan kata-kata ini...",
  ui_story_5010_50100601_72_dialog_content = "Nah, baiklah... Sejak hari ini, aku, Rhein, akan bertindak sebagai...",
  ui_story_5010_50100601_73_dialog_content = "<color=#FFB400>Penguasa</color> baru Umbraton.",
  ui_story_5010_50100601_74_dialog_content = "?!",
  ui_story_5010_50100601_75_dialog_content = "Pria di sebelah Rhein itu Maude, ketua geng setempat yang bernama Solus.",
  ui_story_5010_50100601_76_dialog_content = "Solus adalah salah satu geng paling kuat di Umbraton. Aku tak pernah menyangka mereka mau bekerja sama dengan Blue Lion Guild.",
  ui_story_5010_50100601_77_dialog_content = "Rhein, Maude... Maksud kalian apa, sih?!",
  ui_story_5010_50100601_78_dialog_content = "Bukannya tadi kami sudah meminta kalian...",
  ui_story_5010_50100601_79_dialog_content = "Untuk menutup mulutmu!!",
  ui_story_5010_50100601_80_dialog_content = "*Menghela napas* Lihat, kau membuatku terpaksa mengucapkan serapah seperti orang biasa rendahan...",
  ui_story_5010_50100601_81_dialog_content = "Coba kita ulangi saja... Perhatian, semuanya! Revolusi akbar akan segera dimulai, dan akulah yang akan memimpin Umbraton menuju era baru penuh kejayaan!",
  ui_story_5010_50100601_82_dialog_content = "Suatu kehormatan besar bagiku karena bisa membahas masa depan Umbraton bersama para ketua Guild terhormat yang berkumpul di sini hari ini...",
  ui_story_5010_50100601_83_dialog_content = "Omong-omong soal Shadowlord, yang aku yakin sedang kalian cari-cari, kuyakinkan kalian bahwa dia dan pesawat kesayangannya... kini menjadi bagian dari kekayaan sejarah kota kita ini.",
  ui_story_5010_50100601_84_dialog_content = "Apa yang telah kauperbuat?!",
  ui_story_5010_50100601_85_dialog_content = "Apa maksud perkataannya itu, Luke?",
  ui_story_5010_50100601_86_dialog_content = "Kau tak dengar? Rhein melancarkan kudeta bersenjata!",
  ui_story_5010_50100601_87_dialog_content = "Sial... Terminal kita sama sekali tak berfungsi! Ini pasti ulah Rhein...",
  ui_story_5010_50100601_88_dialog_content = "Kita perlu menemukan cara untuk menyebarkan berita!",
  ui_story_5010_50100601_89_dialog_content = "Tapi dari mana datangnya kepercayaan diri Rhein? Apakah dia benar-benar berpikir dia bisa mengalahkan semua bos di sini?",
  ui_story_5010_50100601_90_dialog_content = "Lihat ke sana, Luke!",
  ui_story_5010_50100601_91_dialog_content = "Sial... Banyak sekali yang berubah menjadi Eclipsite!",
  ui_story_5010_50100601_92_dialog_content = "Tak usah melawan karena hanya akan sia-sia saja!",
  ui_story_5010_50100601_93_dialog_content = "Sebagai wakil Blue Lion Guild... Bukan, sebagai wakil SELURUH Umbraton... Aku setulusnya meminta maaf atas pemandangan kacau ini.",
  ui_story_5010_50100601_94_dialog_content = "Nah, sekarang... Para pemimpin yang terhormat dari berbagai Guild yang ada di Umbraton, serta seluruh hadirin yang datang dari jauh, dengan rendah hati aku meminta kalian untuk menyerah tanpa syarat dan menerima ketentuan-ketentuan berikut ini!",
  ui_story_5010_50100601_95_dialog_content = "Luke, kita...",
  ui_story_5010_50100601_96_dialog_content = "Aku akan melindungimu sementara kau mencari jalan keluar. Setelah itu, kuserahkan kepadamu untuk mencari bantuan untuk kita.",
  ui_story_5010_50100601_97_dialog_content = "Eh? Mau apa kalian?!",
  ui_story_5010_50100601_98_dialog_content = "…?",
  ui_story_5010_50100601_99_dialog_content = "Sepertinya... Kau tak lagi membutuhkan lengan ini!",
  ui_story_5010_50100601_100_dialog_content = "Aaaaaaaargh!!!",
  ui_story_5010_50100601_101_dialog_content = "True Order...?",
  ui_story_5010_50100601_102_dialog_content = "...",
  ui_story_5010_50100601_103_dialog_content = "Seharusnya lelang ini berjalan wajar, tapi kalian malah mengacaukannya...",
  ui_story_5010_50100601_104_dialog_content = "Te-tenanglah, Paloma! Kau sudah menghajarnya sampai pingsan...",
  ui_story_5010_50100601_105_dialog_content = "Tuan Rhein, menurut aturan, dilarang menimbulkan keributan di lelang ini. Sayang sekali... Kami terpaksa memintamu pergi dari sini.",
  ui_story_5010_50100601_106_dialog_content = "...Siapa kau ini? Apa aku mengenalmu?",
  ui_story_5010_50100601_107_dialog_content = "Cukup sudah omong kosong ini. Bunuh mereka semua.",
  ui_story_5010_50100601_108_dialog_content = "Beryl! Paloma!",
  ui_story_5010_50100601_109_dialog_content = "PlayerName?!",
  ui_story_5010_50100601_110_dialog_content = "Kita berjumpa lagi, Sobat. Sayangnya, kita bertemu dalam situasi yang tak mengenakkan seperti ini.",
  ui_story_5010_50100601_111_dialog_content = "Lagi-lagi kau, Caelestite... Tapi, mana anjing peliharaanmu itu?",
  ui_story_5010_50100601_112_dialog_content = "...",
  ui_story_5010_50100601_113_dialog_content = "...Ah, tapi kurasa ini memang sudah bisa diperkirakan. Aku tak mau sampai terpaksa menggunakan kekerasan, tahu?",
  ui_story_5010_50100601_114_dialog_content = "Cih.",
  ui_story_5010_50100601_115_dialog_content = "Biar kutangani orang-orang di sebelah sini. Kalian bereskan yang lainnya.",
  ui_story_5010_50100601_116_dialog_content = "Siap, Pak!",
  ui_story_5010_50100601_117_dialog_content = "Nih, ambil juga ini.",
  ui_story_5010_50100601_118_dialog_content = "Ah! Th-Terima kasih, bos! Semua barang bagus ini...",
  ui_story_5010_50100601_119_dialog_content = "Jangan sampai ada satu pun pil yang terbuang percuma! Demi orde baru Umbraton!",
  ui_story_5010_50100601_120_dialog_content = "Graaaaaagh!!!",
  ui_story_5010_50100601_121_dialog_content = "Pria itu... Barusan dia berubah menjadi Eclipsite?!",
  ui_story_5010_50100601_122_dialog_content = "Berikan perintah, PlayerName!",
  ui_story_5010_50100601_123_dialog_content = "Serahkan saja kepadaku! Faust, kau dan yang lainnya pastikan kedua orang itu tak kabur!",
  ui_story_5010_50100601_124_dialog_content = "Apa-apaan ini? Kau berniat menangkap kami?",
  ui_story_5010_50100601_125_dialog_content = "Hahahaha! Sungguh bocah pemberani!",
  ui_story_5010_50100601_126_dialog_content = "Hei, kenapa kau tertawa? Saya punya beberapa pertanyaan untuk Anda, sekarang ke sini!",
  ui_story_5010_50100601_127_dialog_content = "Jangan mendekat! Dasar wanita sableng.",
  ui_story_5010_50100601_128_dialog_content = "Barusan kau menyebutku apa...?",
  ui_story_5010_50100601_129_dialog_content = "*Menghela napas* Ini akan jadi buruk.",
  ui_story_5010_50100602_1_dialog_content = "...Mampuslah!",
  ui_story_5010_50100602_2_dialog_content = "Uraaaagh...!",
  ui_story_5010_50100602_3_dialog_content = "Hah...? Pittman! Kau ada di sini!",
  ui_story_5010_50100602_4_dialog_content = "Pittman?",
  ui_story_5010_50100602_5_dialog_content = "Selamat malam juga, Paloma...",
  ui_story_5010_50100602_6_dialog_content = "Darah yang mengkristal ini... Ini milik Beryl Gautier!",
  ui_story_5010_50100602_7_dialog_content = "Halo! Aku sudah dengar banyak tentangmu, Tuan Penyelidik!",
  ui_story_5010_50100602_8_dialog_content = "Nona Beryl Gautier... Aku Wayne Pittman dari Lumo Hall of Justice. Aku harus memintamu ikut denganku sekarang juga...",
  ui_story_5010_50100602_9_dialog_content = "Hah? Apa itu berarti aku ditangkap?",
  ui_story_5010_50100602_10_dialog_content = "Sepertinya penyelidikanmu belum mengalami kemajuan, Pittman...",
  ui_story_5010_50100602_11_dialog_content = "Anu... Paloma? Pittman kemari bukan untuk mengejar kalian. Dia kemari karena...",
  ui_story_5010_50100602_12_dialog_content = "\"Enhancer\", atau lebih tepatnya, pil yang baru saja ditelan kroni Blue Lion Guild itu...",
  ui_story_5010_50100602_13_dialog_content = "Tunggu, apa maksudmu?",
  ui_story_5010_50100602_14_dialog_content = "Paloma... Aku khawatir bahwa teknik modifikasi Mirren Gautier berhubungan dengan Enhancer itu.",
  ui_story_5010_50100602_15_dialog_content = "Mirren Gautier...",
  ui_story_5010_50100602_16_dialog_content = "Pertama, kita tundukkan dulu para begundal itu. Kita kemari bukan hanya untuk berkelakar tanpa ujung.",
  ui_story_5010_50100602_17_dialog_content = "Tapi, ke mana perginya Rhein? Atau pria bertongkat itu?",
  ui_story_5010_50100602_18_dialog_content = "Mereka pasti sudah pergi diam-diam.",
  ui_story_5010_50100602_19_dialog_content = "Tapi, kenapa mereka memilih lelang ini sebagai sasaran serangan mereka?",
  ui_story_5010_50100602_20_dialog_content = "Aku yakin jawabannya lebih rumit daripada yang kita kira. Ini semua pasti bagian dari rencana mereka.",
  ui_story_5010_50100602_21_dialog_content = "Kita hampir kehabisan waktu. Kita harus...",
  ui_story_5010_50100602_22_dialog_content = "Nona-nona, maaf menyela, tapi aku sudah menemukan apa yang kita cari.",
  ui_story_5010_50100602_23_dialog_content = "Kau sudah menemukannya?",
  ui_story_5010_50100602_24_dialog_content = "Karena Blue Lion Guild sudah melanggar aturan lelang...",
  ui_story_5010_50100602_25_dialog_content = "Aku yakin mereka tak akan ragu melanggar aturan lain.",
  ui_story_5010_50100602_26_dialog_content = "Aku benar-benar minta maaf, PlayerName, tapi aku dan nona-nona ini harus berpisah denganmu untuk sekarang.",
  ui_story_5010_50100602_27_dialog_content = "Mungkin kita akan bertemu lagi suatu hari nanti... Semoga Truth memberkatimu.",
  ui_story_5010_50100602_28_dialog_content = "Se-Selamat tinggal, PlayerName...",
  ui_story_5010_50100602_29_dialog_content = "Oh! Eee, jaga diri kalian bertiga baik-baik!",
  ui_story_5010_50100602_30_dialog_content = "Mereka sudah pergi... Apa semua orang dari True Order memang suka datang dan pergi sesukanya seperti angin?",
  ui_story_5010_50100602_31_dialog_content = "Beryl Gautier! Kembalilah, Beryl Gautier...!",
  ui_story_5010_50100602_32_dialog_content = "Ah... Lupakan saja, PlayerName. Aku yakin Rhein masih punya rencana lagi untuk kita semua.",
  ui_story_5010_50100602_33_dialog_content = "Terminal kita masih belum bisa berfungsi...",
  ui_story_5010_50100602_34_dialog_content = "Lihat di sana! Itu isyarat asap, asalnya dari arah Markas Guild!",
  ui_story_5010_50100602_35_dialog_content = "Dalam kondisi normal, pasukan keamanan Umbraton akan langsung dikerahkan untuk mengendalikan situasi.",
  ui_story_5010_50100602_36_dialog_content = "Apa pasukan garnisun Umbraton benar-benar bisa mengalahkan Enhancer?",
  ui_story_5010_50100602_37_dialog_content = "Eee... Jujur? Kurasa mereka tak akan sanggup melawannya.",
  ui_story_5010_50100602_38_dialog_content = "Kita harus ke markas besar dan memastikan situasinya.",
  ui_story_5010_50100602_39_dialog_content = "Aku setuju... Tunjukkan jalannya, Luke!",
  ui_story_5010_50100602_40_dialog_content = "Lewat sini!",
  ui_story_5010_50100701_1_dialog_content = "True Order... Ternyata mereka lebih merepotkan daripada yang kuduga.",
  ui_story_5010_50100701_2_dialog_content = "Walau begitu, rencana sudah dijalankan, dan kemenangan sudah hampir kita gapai.",
  ui_story_5010_50100701_3_dialog_content = "Tampaknya memang begitu, tapi menurutku, sebaiknya kita tak terburu-buru mengeluarkan <color=#FFB400>kartu as</color>.",
  ui_story_5010_50100701_4_dialog_content = "Lady Bethel! Syukurlah! Kau harus menyelamatkan...!",
  ui_story_5010_50100701_5_dialog_content = "Hahahahaha!",
  ui_story_5010_50100701_6_dialog_content = "Siapa kau? Berani-beraninya kau menyerang anggota Markas Umbraton Guild!",
  ui_story_5010_50100701_7_dialog_content = "Heh... Kami hanya bertindak atas perintah Shadowlord yang baru! Markas Umbraton Guild kini menjadi miliknya!",
  ui_story_5010_50100701_8_dialog_content = "...Kau sadar tidak sih, apa yang kaubilang barusan?",
  ui_story_5010_50100701_9_dialog_content = "Ha, tentu saja aku tahu, dasar wanita bodoh! Hari ini adalah hari kematianmu!!",
  ui_story_5010_50100701_10_dialog_content = "Sepertinya kalian semua siap mati demi mencapai tujuan kalian.",
  ui_story_5010_50100701_11_dialog_content = "Kalau begitu...",
  ui_story_5010_50100701_12_dialog_content = "...Argh!!",
  ui_story_5010_50100701_13_dialog_content = "Saya senang untuk membantu.",
  ui_story_5010_50100701_14_dialog_content = "Kami tak menyangka kaulah yang akan menjawab panggilan minta bantuan dari kami, Lady Bethel...",
  ui_story_5010_50100701_15_dialog_content = "Jumlah mereka banyak sekali. Mereka bilang Shadowlord yang barulah yang mengendalikan semuanya, dan bahwa kami...",
  ui_story_5010_50100701_16_dialog_content = "Tunggu... Semuanya, awas!",
  ui_story_5010_50100701_17_dialog_content = "Perasaan ini... Sensasi kekuatan yang tak ada tandingannya! Hahahahaha!!!",
  ui_story_5010_50100701_18_dialog_content = "Pertarungannya tampak sengit... Para penyerang itu sekarang pasti sudah berhasil menembus masuk ke aula utama.",
  ui_story_5010_50100701_19_dialog_content = "Barusan itu suara Bethel!",
  ui_story_5010_50100701_20_dialog_content = "Tunggu... Lagi-lagi perasaanku aneh... Jangan-jangan...?",
  ui_story_5010_50100701_21_dialog_content = "Benar! Mereka menggunakan \"Enhancer\" itu lagi!",
  ui_story_5010_50100701_22_dialog_content = "Bethel!",
  ui_story_5010_50100701_23_dialog_content = "PlayerName! Aku di sini!",
  ui_story_5010_50100701_24_dialog_content = "Sepuluh kali... Tidak, dua puluh kali... Kalian semua, coba lihat baik-baik!",
  ui_story_5010_50100701_25_dialog_content = "Berapa banyak pil yang diminum pria itu?",
  ui_story_5010_50100701_26_dialog_content = "Kami ke sana, Bethel! Bertahanlah!",
  ui_story_5010_50100801_1_dialog_content = "Bethel! Mereka anak buah Maude! Tadi dia dan Rhein menyerang lelang bawah tanah yang kami datangi!",
  ui_story_5010_50100801_2_dialog_content = "Rhein bilang, Shadowlord... sekarang tinggal sejarah.",
  ui_story_5010_50100801_3_dialog_content = "Saat kaubilang bahwa Shadowlord diserang, apa yang kau...",
  ui_story_5010_50100801_4_dialog_content = "Aku masih belum berhasil menghubunginya, dan orang-orang yang kusuruh mencarinya juga belum memberiku kabar.",
  ui_story_5010_50100801_5_dialog_content = "Yang kutahu hanyalah bahwa pesawat Shadowlord mengalami kecelakaan...",
  ui_story_5010_50100801_6_dialog_content = "Kalau begitu, kenapa kau berada di markas besar ini?",
  ui_story_5010_50100801_7_dialog_content = "Aku melihat sinyal minta bantuan dari kalian dari jauh, dan aku langsung kemari secepat mungkin.",
  ui_story_5010_50100801_8_dialog_content = "Lady Bethel! Kami tim tanggap pertama dari pasukan keamanan Umbraton...",
  ui_story_5010_50100801_9_dialog_content = "Aku tahu, aku tahu. Apa ada kabar baru?",
  ui_story_5010_50100801_10_dialog_content = "Blue Lion Guild, bersama Solus, telah merencanakan kudeta habis-habisan.",
  ui_story_5010_50100801_11_dialog_content = "Target pemberontakan bersenjata mereka mencakup semua guild besar, lelang bawah tanah, dan rumah besar Shadowlord...",
  ui_story_5010_50100801_12_dialog_content = "Langkah penanganan darurat sudah diterapkan, dan...",
  ui_story_5010_50100801_13_dialog_content = "Apa ada yang sudah berhasil berkomunikasi dengan Shadowlord?",
  ui_story_5010_50100801_14_dialog_content = "A-Akibat cuaca tak wajar hari ini, kini semua terminal di dalam kota tak berfungsi. Kami tak bisa menghubungi Shadowlord, tapi ada kabar yang bilang bahwa Rhein sudah...",
  ui_story_5010_50100801_15_dialog_content = "Cukup. Lanjutkan tugasmu.",
  ui_story_5010_50100801_16_dialog_content = "Dan waspadai monster-monster itu! Mereka bisa berubah sewaktu-waktu!",
  ui_story_5010_50100801_17_dialog_content = "Kalian! Cari cara untuk memulihkan komunikasi di dalam kota. Kita harus memastikan situasi di setiap sektor, dan menyelamatkan orang-orang yang mungkin belum terselamatkan!",
  ui_story_5010_50100801_18_dialog_content = "Ta-Tapi Lady Bethel, perintah utama yang kami terima adalah melindungi bagian dalam kota...",
  ui_story_5010_50100801_19_dialog_content = "...",
  ui_story_5010_50100801_20_dialog_content = "Maaf, tapi itu perintah dari Shadowlord. Permisi, Lady Bethel.",
  ui_story_5010_50100801_21_dialog_content = "Heh, seperti itulah Lord Istvan-mu.",
  ui_story_5010_50100801_22_dialog_content = "Apa Rhein dan anak buahnya sudah sinting? Seberapa besar kekuatan mereka sebenarnya sampai-sampai mereka berani menantang seluruh Umbraton sekaligus?",
  ui_story_5010_50100801_23_dialog_content = "Umbraton tidaklah sekompak seperti yang kaukira, Bethel.",
  ui_story_5010_50100801_24_dialog_content = "Setiap Guild, setiap geng... Yah, setiap orang punya kepentingan masing-masing yang mereka dahulukan. Heh...",
  ui_story_5010_50100801_25_dialog_content = "Aku berani bertaruh, sekarang ini setiap organisasi pasti sedang mencari cara untuk menyelamatkan diri mereka sendiri. Kalau situasinya sudah seperti ini, mungkin bahkan ada yang memilih untuk memihak Rhein.",
  ui_story_5010_50100801_26_dialog_content = "Karena itulah, tadi mereka memilih menyerang lelang itu secara personal. Karena semua bos besar ada di sana, dia bisa melibatkan mereka semua dalam kerusuhan itu.",
  ui_story_5010_50100801_27_dialog_content = "Tanpa persetujuan Lumopolis, apa Rhein bisa benar-benar...",
  ui_story_5010_50100801_28_dialog_content = "Maaf membuatmu kecewa, Yang Mulia... Tapi, ini Umbraton.",
  ui_story_5010_50100801_29_dialog_content = "Setiap orang di sini mematuhi hukum Umbraton demi keuntungan mereka sendiri, dan setiap orang menjaga ketertiban di sini karena kekuatan Istvan.",
  ui_story_5010_50100801_30_dialog_content = "Bagi sebagian orang di sini, tak penting siapa yang bertindak sebagai Shadowlord...",
  ui_story_5010_50100801_31_dialog_content = "Tapi, cara Rhein memang terlalu kasar. Kalau dia mengambil alih kuasa atas kota ini, aku tak yakin hasilnya akan baik.",
  ui_story_5010_50100801_32_dialog_content = "Kalaupun ternyata Rhein memang berhasil mengalahkan Istvan, dan kalaupun dia berhasil menundukkan seluruh Umbraton, Lumopolis tak akan pernah mengakuinya...",
  ui_story_5010_50100801_33_dialog_content = "Aduh! Tak ada gunanya kita membahasnya sekarang! Prioritas utama kita adalah mencari Shadowlord!",
  ui_story_5010_50100801_34_dialog_content = "Tapi, kalau apa yang dibilang Rhein memang benar, Nona Bethel, berarti Shadowlord...",
  ui_story_5010_50100801_35_dialog_content = "Aku tak mau memercayainya, Luke!",
  ui_story_5010_50100801_36_dialog_content = "Kaubilang tak penting siapa yang bertindak sebagai Shadowlord di Umbraton, Luke... Tapi, bukan berarti kita bisa membiarkan Rhein berbuat seenak jidatnya sendiri, 'kan?",
  ui_story_5010_50100801_37_dialog_content = "Benar. Apa pun caranya, kita harus menghentikannya. Kalau situasi terus seperti ini, akan ada lebih banyak orang yang mati.",
  ui_story_5010_50100801_38_dialog_content = "Aku akan mengumpulkan pengunjung dari Lumopolis dan mencari cara untuk meminta bantuan dari kota.",
  ui_story_5010_50100801_39_dialog_content = "Lihat! Isyarat asap itu sama seperti yang digunakan oleh tentara bayaran kami dalam situasi darurat... Dan asalnya dari arah guild <color=#FFB400>Lin Family</color>!",
  ui_story_5010_50100801_40_dialog_content = "Jumlah petarung mereka yang ditempatkan di kota tak banyak, jadi mereka adalah salah satu sasaran paling empuk untuk diserang.",
  ui_story_5010_50100801_41_dialog_content = "Pertahanan kota bagian dalam kokoh. Bahkan Rhein akan kesulitan untuk menerobos.",
  ui_story_5010_50100801_42_dialog_content = "Hah? Lin Guild mungkin juga sedang diserang?",
  ui_story_5010_50100801_43_dialog_content = "Aku harus membantu mereka!",
  ui_story_5010_50100801_44_dialog_content = "Tugasku tetap melindungimu, PlayerName. Kalau kau pergi, aku ikut.",
  ui_story_5010_50100801_45_dialog_content = "Di Umbraton, semua orang berusaha untuk diri mereka sendiri... Kurasa kitalah satu-satunya orang di sini yang punya keahlian tempur sungguhan.",
  ui_story_5010_50100801_46_dialog_content = "Kalau begitu, kita pergi bersama!",
  ui_story_5010_50100901_1_dialog_content = "Ka... Kau... Aduh...",
  ui_story_5010_50100901_2_dialog_content = "*Wusss...*",
  ui_story_5010_50100901_3_dialog_content = "Siapa ini?",
  ui_story_5010_50100901_4_dialog_content = "Ini salah satu anak buahku!",
  ui_story_5010_50100901_5_dialog_content = "L... Luke?",
  ui_story_5010_50100901_6_dialog_content = "Kau baik-baik saja, saudaraku? Siapa yang melakukannya kepadamu?!",
  ui_story_5010_50100901_7_dialog_content = "Aku masih bisa bertahan, tapi Solus... Mereka sudah berhasil menembus masuk.",
  ui_story_5010_50100901_8_dialog_content = "Saat ini, para petarung paling kuat dari Lin Family berada jauh dari kota... Mereka hanya bisa mengandalkan pasukan pertahanan kota untuk sementara ini. Situasi mereka buruk...",
  ui_story_5010_50100901_9_dialog_content = "Jangan khawatir soal itu. Cari saja tempat aman dan istirahatlah.",
  ui_story_5010_50100901_10_dialog_content = "...",
  ui_story_5010_50100901_11_dialog_content = "Di dalam... Mereka menggunakan Enhancer lagi!",
  ui_story_5010_50100901_12_dialog_content = "Kita harus bergegas!",
  ui_story_5010_50100901_13_dialog_content = "Sepertinya kita harus menyingkirkan gangguan di seluruh tempat ini, ya? Sepertinya seru.",
  ui_story_5010_50100901_14_dialog_content = "Memang. Aku sudah tak sabar...",
  ui_story_5010_50100901_15_dialog_content = "Rantai! Memanjang!",
  ui_story_5010_50100901_16_dialog_content = "Graaoooooh!!!",
  ui_story_5010_50100902_1_dialog_content = "Hujannya mulai turun sangat deras sekarang.",
  ui_story_5010_50100902_2_dialog_content = "Tunggu sampai Lin Family pulang dan melihat betapa berantakannya tempat ini...",
  ui_story_5010_50100902_3_dialog_content = "Bethel.",
  ui_story_5010_50100902_4_dialog_content = "Hmm?",
  ui_story_5010_50100902_5_dialog_content = "Aku masih belum paham... Kenapa Blue Lion Guild menyatukan kekuatan dengan Solus?",
  ui_story_5010_50100902_6_dialog_content = "Sepertinya Rhein atau Maude tidak benar-benar akan mendapatkan keuntungan melalui kerja sama mereka itu.",
  ui_story_5010_50100902_7_dialog_content = "Bukan itu saja, dulu mereka juga sering berseteru. Lagi pula, sebagian besar operasi mereka dilakukan secara rahasia, jadi mereka selalu bersaing satu sama lain.",
  ui_story_5010_50100902_8_dialog_content = "Jadi, kalau tiba-tiba saja mereka memutuskan untuk bekerja sama... Kenapa tidak dari dulu saja?",
  ui_story_5010_50100902_9_dialog_content = "Kenapa mereka memilih menunggu sampai hari ini untuk menjalankan kudeta...?",
  ui_story_5010_50100902_10_dialog_content = "Itu karena jadwal perjalanan Shadowlord. Tadi pagi, dia berangkat dari kota ini dengan pesawatnya...",
  ui_story_5010_50100902_11_dialog_content = "Serta badai yang tak wajar ini.",
  ui_story_5010_50100902_12_dialog_content = "Pola cuaca aneh yang mengganggu sistem komunikasi, dan orang-orang yang berubah menjadi Eclipsite... Aku pernah melihat kejadian seperti ini.",
  ui_story_5010_50100902_13_dialog_content = "Di Dunefire... Di Eraveil... *Menghela napas*",
  ui_story_5010_50100902_14_dialog_content = "Beri tahu aku, Bethel: menurutmu, kira-kira apa yang menjadi motivasi mereka berdua untuk melancarkan serangan seperti tadi itu?",
  ui_story_5010_50100902_15_dialog_content = "Aku tak tahu bagaimana mereka bisa mendapatkan keuntungan dengan menimbulkan kerusuhan di kota seperti ini...",
  ui_story_5010_50100902_16_dialog_content = "Kecuali kalau tujuannya adalah menancapkan monopoli atas perdagangan bawah tanah?",
  ui_story_5010_50100902_17_dialog_content = "Tapi, selama ini Shadowlord tak peduli dengan hal-hal itu. Dia tak pernah terang-terangan menentangnya.",
  ui_story_5010_50100902_18_dialog_content = "Memang, banyak produk mencurigakan keluar-masuk dengan bebas.",
  ui_story_5010_50100902_19_dialog_content = "Itulah sebabnya...",
  ui_story_5010_50100902_20_dialog_content = "Apa pun alasan kudeta mereka, pastilah alasannya lebih dari sekadar untuk memonopoli perdagangan bawah tanah.",
  ui_story_5010_50100902_21_dialog_content = "Tapi, kira-kira apa alasannya...",
  ui_story_5010_50100902_22_dialog_content = "Maaf menyela, Bethel, tapi kurasa Frankel...",
  ui_story_5010_50100902_23_dialog_content = "Guk! Guk-guk!",
  ui_story_5010_50100902_24_dialog_content = "Ada apa, Frankel?",
  ui_story_5010_50100902_25_dialog_content = "Guk! Guk, guk!",
  ui_story_5010_50100902_26_dialog_content = "Yang di sana itu apa? Itu...",
  ui_story_5010_50100902_27_dialog_content = "Kupu-kupu?",
  ui_story_5010_50100902_28_dialog_content = "Hah?",
  ui_story_5010_50100902_29_dialog_content = "Ada sejumlah kupu-kupu di bawah batas atap...",
  ui_story_5010_50100902_30_dialog_content = "Ini bukan waktunya untuk mengamati alam, Luke.",
  ui_story_5010_50100902_31_dialog_content = "Bisa tolong alihkan rasa penasaranmu dari serangga dan fokus saja untuk menyelamatkan rekan-rekan Aurorian kita?",
  ui_story_5010_50100902_32_dialog_content = "...Ada sesuatu yang terjadi pada Steelfire Gang.",
  ui_story_5010_50100902_33_dialog_content = "Tu-Tunggu, siapa itu Steelfire Gang? Dan bagaimana kau bisa tahu ada sesuatu yang terjadi pada mereka?",
  ui_story_5010_50100902_34_dialog_content = "Kupu-kupu jenis ini sangat sensitif terhadap perubahan suhu. Seharusnya mereka tidak berada di sini pada bulan-bulan ini.",
  ui_story_5010_50100902_35_dialog_content = "Tapi, Steelfire Gang punya kurungan dan ada beberapa kupu-kupu itu di dalamnya. Beberapa waktu lalu, aku menerima pekerjaan untuk memperbaiki kurungan itu.",
  ui_story_5010_50100902_36_dialog_content = "Lihat ke batas atap itu dan buktikan saja sendiri.",
  ui_story_5010_50100902_37_dialog_content = "Kupu-kupu itu... Mereka kemari untuk berlindung dari hujan, dan mereka tertarik oleh suhu tubuh kita.",
  ui_story_5010_50100902_38_dialog_content = "Ada kemungkinan kurungan milik Steelfire Gang itu terbuka... Itu semacam isyarat!",
  ui_story_5010_50100902_39_dialog_content = "Dan hanya kaulah yang bisa memahami isyarat itu, Luke. Aneh sekali...",
  ui_story_5010_50100902_40_dialog_content = "Aku penasaran, apa yang akan kita temui di sana?",
  ui_story_5010_50100902_41_dialog_content = "Mana kutahu... Hanya ini satu-satunya petunjuk kita.",
  ui_story_5010_50100902_42_dialog_content = "Memang, meski hanya untuk membantu menjaga ketertiban... Kita tidak bisa duduk diam.",
  ui_story_5010_50100902_43_dialog_content = "Syukurlah ada kau yang bisa memahaminya, Luke.",
  ui_story_5010_50100902_44_dialog_content = "Bukan masalah. Tapi, aku kasihan kepada kupu-kupu itu.",
  ui_story_5010_50100902_45_dialog_content = "Dengan suhu seperti ini... Mereka hanya bisa bertahan hidup sekitar setengah jam lagi.",
  ui_story_5010_50100902_46_dialog_content = "Markas Steelfire Gang berada di dataran rendah yang dikelilingi permukiman kumuh.",
  ui_story_5010_50100902_47_dialog_content = "Kalau mereka diserang, tak bisa kubayangkan kehancuran yang akan ditanggungnya...",
  ui_story_5010_50100902_48_dialog_content = "Kita tak akan tahu apa-apa kalau hanya berdiri saja di sini. Ayo pergi.",
  ui_story_5010_50101002_1_dialog_content = "Syukurlah... Kita berhasil menyelamatkan mereka semua.",
  ui_story_5010_50101002_2_dialog_content = "Aku tak pernah menyangka Rhein dan Maude juga akan menarget mereka.",
  ui_story_5010_50101002_3_dialog_content = "Ini tak masuk akal... Sepertinya dia tergesa-gesa pergi sebelum sempat melakukan apa yang ingin dilakukannya.",
  ui_story_5010_50101002_4_dialog_content = "...Sudahlah, kita harus mengurus orang-orang yang terluka. Untunglah cedera mereka relatif ringan.",
  ui_story_5010_50101002_5_dialog_content = "Aku sudah meninggalkan isyarat untuk White Flame Mercenaries. Seharusnya tak lama lagi mereka akan sampai di sini untuk membantu kita.",
  ui_story_5010_50101002_6_dialog_content = "Kok kau berhasil menghubungi mereka?",
  ui_story_5010_50101002_7_dialog_content = "Aku meninggalkan jejak lendir khusus di belakang kita. Jejak itu tak akan hilang walau terkena hujan, dan bahkan bisa bercahaya dalam gelap.",
  ui_story_5010_50101002_8_dialog_content = "...Pasti asalnya dari kawanan seranggamu itu, 'kan?",
  ui_story_5010_50101002_9_dialog_content = "Benar sekali!",
  ui_story_5010_50101002_10_dialog_content = "Sebentar, apa yang terjadi di sini...",
  ui_story_5010_50101002_11_dialog_content = "Kabur! Ke puncak!",
  ui_story_5010_50101002_12_dialog_content = "Mana Steelfire Gang? Tak ada yang bisa menyelamatkan kita sekarang!",
  ui_story_5010_50101002_13_dialog_content = "Siapa bilang?",
  ui_story_5010_50101002_14_dialog_content = "Tempat ini... Aroma laut dalam meresap ke tempat ini.",
  ui_story_5010_50101002_15_dialog_content = "Suplai darurat ini untuk kalian semua!",
  ui_story_5010_50101002_16_dialog_content = "Rakit, alat pelampung, dan ransum darurat!",
  ui_story_5010_50101002_17_dialog_content = "Dengar!",
  ui_story_5010_50101002_18_dialog_content = "Jangan habiskan semua suplai itu seperti anak anjing kelaparan!",
  ui_story_5010_50101002_19_dialog_content = "Itu Istvan Gang! Istvan Gang kemari untuk menyelamatkan kita!!!",
  ui_story_5010_50101002_20_dialog_content = "Kita selamat!! Syukurlah kalian kemari!",
  ui_story_5010_50101002_21_dialog_content = "Apa Shadowlord memerintahkan kalian untuk mempertahankan tempat ini?",
  ui_story_5010_50101002_22_dialog_content = "Katakan, apa dia selamat dan baik-baik saja?!",
  ui_story_5010_50101002_23_dialog_content = "Mana kutahu? Para dewa pun belum tentu tahu soal itu, Lady Bethel.",
  ui_story_5010_50101002_24_dialog_content = "Kami sedang memperbaikinya dari atas ke bawah, Bos!",
  ui_story_5010_50101002_25_dialog_content = "Bagaimana situasi di bagian lain kota?",
  ui_story_5010_50101002_26_dialog_content = "Apa ada informasi tentang korban dan kerugiannya? Mana Solus dan Blue Lion sekarang? Apa ada yang melihat Maude atau Rhein?",
  ui_story_5010_50101002_27_dialog_content = "...Kau terlalu banyak cincong.",
  ui_story_5010_50101002_28_dialog_content = "Belum ada korban dan kerugian, tak tahu mereka ada di mana, dan belum, kami belum melihat mereka.",
  ui_story_5010_50101002_29_dialog_content = "Mengurus orang-orang yang terluka saja sudah cukup melelahkan. Jangan bertanya apa-apa lagi.",
  ui_story_5010_50101002_30_dialog_content = "Walau begitu, Guild yang tadi diserang kini sudah dalam perlindungan kami!",
  ui_story_5010_50101002_31_dialog_content = "Jumlah musuh juga sudah mulai berkurang...",
  ui_story_5010_50101002_32_dialog_content = "Mereka pasti ketakutan melihat kehadiran kita yang heroik ini. Ya, pasti begitu.",
  ui_story_5010_50101002_33_dialog_content = "Tunggu... Maksudmu, sudah tak ada lagi anggota Solus di kota?",
  ui_story_5010_50101002_34_dialog_content = "Ini tak sejalan dengan pergerakan mereka sebelumnya...",
  ui_story_5010_50101002_35_dialog_content = "Apa hanya perasaanku saja, atau tinggi permukaan air di sini makin lama makin naik?",
  ui_story_5010_50101002_36_dialog_content = "Kurasa begitu... Tentakelku tidak bisa istirahat.",
  ui_story_5010_50101002_37_dialog_content = "Tidak, lihat! Airnya... Airnya mulai mengalir ke sini!!",
  ui_story_5010_50101002_38_dialog_content = "Permukiman kumuh ini berada di area dataran rendah.",
  ui_story_5010_50101002_39_dialog_content = "Untunglah Istvan Gang kemari untuk membantu...",
  ui_story_5010_50101002_40_dialog_content = "Tak bisa kubayangkan seberapa besar masalah yang akan dihadapi orang-orang ini seandainya kalian tak ada.",
  ui_story_5010_50101002_41_dialog_content = "Sial!",
  ui_story_5010_50101002_42_dialog_content = "Kalau terus-menerus hujan seperti ini, kapal dan dermaga di Gold River akan terancam bahaya!",
  ui_story_5010_50101002_43_dialog_content = "Permukiman kumuh... Dermaga dan kapal... Dan hujan deras ini...",
  ui_story_5010_50101002_44_dialog_content = "Ah! Rupanya itulah yang terjadi! Akhirnya aku paham!",
  ui_story_5010_50101002_45_dialog_content = "<size=45><color=#FFB400>Bendungan Bekas Luka!</color></size>",
  ui_story_5010_50101002_46_dialog_content = "Itu target mereka! Bendungan Bekas Luka!",
  ui_story_5010_50101002_47_dialog_content = "...Aku paham!",
  ui_story_5010_50101002_48_dialog_content = "Kalau bendungannya sampai runtuh...",
  ui_story_5010_50101002_49_dialog_content = "Umbraton akan menanggung korban dan kerugian sangat besar. Bukan saja permukiman kumuhnya akan musnah seluruhnya, tapi rute dagang penting di kota juga akan rusak parah.",
  ui_story_5010_50101002_50_dialog_content = "Ini... Ini jauh lebih parah daripada yang kubayangkan!",
  ui_story_5010_50101002_51_dialog_content = "Bagaimana kita bisa mencari tahu tentang situasi bendungan itu sekarang?",
  ui_story_5010_50101002_52_dialog_content = "Menilai dari jumlah air di sini, aman untuk mengatakan bahwa itu belum terkena dampak kritis.",
  ui_story_5010_50101002_53_dialog_content = "Tapi, kita harus terus bergerak, dan harus cepat!",
  ui_story_5010_50101101_1_dialog_content = "Bendungannya di depan sana. Ayo kita intai dulu areanya.",
  ui_story_5010_50101101_2_dialog_content = "*Terkesiap* Di sana! Itu Maude!",
  ui_story_5010_50101101_3_dialog_content = "Sial... Bendungannya sudah tertembus!",
  ui_story_5010_50101101_4_dialog_content = "Sepertinya tak akan bertahan lama lagi...",
  ui_story_5010_50101101_5_dialog_content = "Kaulihat itu? Mereka menggunakan senjata api.",
  ui_story_5010_50101101_6_dialog_content = "Cepat, sebelum terlambat!",
  ui_story_5010_50101101_7_dialog_content = "Lord Maude! Lord Rhein!",
  ui_story_5010_50101101_8_dialog_content = "Oh? Rupanya mereka berhasil menemukan kita.",
  ui_story_5010_50101101_9_dialog_content = "Apa kau juga kemari untuk menyaksikan bendungan itu runtuh, Lady Bethel?",
  ui_story_5010_50101101_10_dialog_content = "Tak usah khawatir. Kau akan segera berkumpul lagi dengan ayahmu tercinta, Lord Istvan.",
  ui_story_5010_50101101_11_dialog_content = "Cukup sudah basa-basinya. Serang!",
  ui_story_5010_50101101_12_dialog_content = "Jangan kira kami akan membiarkanmu lari dari tanggung jawab!",
  ui_story_5010_50101101_13_dialog_content = "Dalam mimpimu pun kami tak akan membiarkanmu kabur, dasar pengkhianat!",
  ui_story_5010_50101101_14_dialog_content = "Sana, kau yang tangani hama-hama rendahan ini.",
  ui_story_5010_50101101_15_dialog_content = "Aku punya urusan lain yang jauh lebih penting. Aku butuh konsentrasi penuh untuk itu...",
  ui_story_5010_50101101_16_dialog_content = "Untuk menyiapkan kejutan besar untuk seluruh Umbraton.",
  ui_story_5010_50101101_17_dialog_content = "Tak akan kubiarkan kau menghancurkan bendungan itu!",
  ui_story_5010_50101101_18_dialog_content = "Uwaaa!!",
  ui_story_5010_50101101_19_dialog_content = "Masa iya harus aku sendiri yang turun tangan mengurus orang-orang kacangan ini...?",
  ui_story_5010_50101101_20_dialog_content = "Kurasa aku perlu pemanasan dulu...",
  ui_story_5010_50101101_21_dialog_content = "Dengan menikmati perlawanan terakhir kalian yang sia-sia!",
  ui_story_5010_50101101_22_dialog_content = "Sepertinya kalian berdua sangat bersemangat.",
  ui_story_5010_50101101_23_dialog_content = "<size=45>K... Kau...?!</size>",
  ui_story_5010_50101101_24_dialog_content = "<size=45>Bagaimana... Bagaimana mungkin kau masih hidup?!</size>",
  ui_story_5010_50101101_25_dialog_content = "Seharusnya kau sudah hancur berkeping-keping!",
  ui_story_5010_50101101_26_dialog_content = "Maude... Aku terpaksa bilang, caramu menyambut tamu baru sungguh kurang sopan.",
  ui_story_5010_50101101_27_dialog_content = "Menghancurkan pesawat saya hanya memberi saya beberapa goresan, tidak lebih ...",
  ui_story_5010_50101101_28_dialog_content = "Sekarang aku ada di hadapanmu... Itu membuktikan bahwa upayamu benar-benar gagal.",
  ui_story_5010_50101101_29_dialog_content = "Setiap anggota Solus yang bertanggung jawab atas pemberontakan di kota sudah ditangkap, begitu pula orang-orang yang membantu mereka.",
  ui_story_5010_50101101_30_dialog_content = "Hahaha... Harus kuakui, monster-monster hasil transformasi itu memang cukup menantang, tapi...",
  ui_story_5010_50101101_31_dialog_content = "Solus kini sudah binasa, dan Blue Lion Guild pun akan menemui nasib serupa.",
  ui_story_5010_50101101_32_dialog_content = "Aset kalian akan dibagi rata kepada seluruh warga Umbraton sebagai kompensasi atas masalah yang telah kalian timbulkan. Atas nama para pemimpin kota... Aku ingin menyampaikan terima kasih sebesar-besarnya atas sumbangan kalian yang sangat besar ini! Hahahahaha!",
  ui_story_5010_50101101_33_dialog_content = "Kukira kau bisa menghentikan kami dengan kata-kata kosongmu itu?",
  ui_story_5010_50101101_34_dialog_content = "Kurasa dia mengatakan yang sebenarnya. Lihat isyarat asap yang mengepul dari kota itu...",
  ui_story_5010_50101101_35_dialog_content = "Sepertinya kita harus mengubah strategi, Maude...",
  ui_story_5010_50101101_36_dialog_content = "Ini sudah berakhir bagimu, Rhein.",
  ui_story_5010_50101101_37_dialog_content = "Bagiku... Aku, hanya aku saja, sudah lebih dari cukup!!",
  ui_story_5010_50101101_38_dialog_content = "Akan kubuat tempat ini menjadi tempat peristirahatan terakhir untuk semua orang di sini!!!",
  ui_story_5010_50101101_39_dialog_content = "Kekuatan... Kekuatan tanpa batas... Milikku!!!",
  ui_story_5010_50101101_40_dialog_content = "Ini dia... Maude akan meminum pil-pil itu!!!",
  ui_story_5010_50101101_41_dialog_content = "Di-Dia melakukannya... Maude menenggak semua pil itu... Dia tampak sangat berbeda dari orang-orang lain yang juga meminum pil itu!",
  ui_story_5010_50101101_42_dialog_content = "Tekanan besar apa ini?!",
  ui_story_5010_50101101_43_dialog_content = "<anim type=Shake><size=45>Graaaaaaaaagh!!!</size></anim>",
  ui_story_5010_50101101_44_dialog_content = "<anim type=Shake><size=45>Kekuatan...</size></anim>",
  ui_story_5010_50101101_45_dialog_content = "Semuanya, bersama-sama! Serang!",
  ui_story_5010_50101101_46_dialog_content = "Ayah, kau masih cedera. Biar kami saja yang melawan Maude. Ayah lindungi saja bendungannya!",
  ui_story_5010_50101101_47_dialog_content = "Di kirimu, Luke!",
  ui_story_5010_50101101_48_dialog_content = "Awas, dia mau menyerang!",
  ui_story_5010_50101101_49_dialog_content = "Akhirnya... Akhirnya tiba juga saatnya.",
  ui_story_5010_50101101_50_dialog_content = "Semuanya, dengarkan perintahku!!!",
  ui_story_5010_50101201_1_dialog_content = "Kau terlambat, PlayerName. Shadowlord sudah dari tadi menunggumu!",
  ui_story_5010_50101201_2_dialog_content = "Oh! Su-Sungguh? Aku berlari secepat mungkin...",
  ui_story_5010_50101201_3_dialog_content = "Tapi, dengan tubuhmu yang kerempeng itu, kurasa keterlambatanmu bisa dimaklumi.",
  ui_story_5010_50101201_4_dialog_content = "Bisa tidak, sih, kau bicara jujur sekali saja? Tentakelmu tak akan copot karenanya, 'kan?",
  ui_story_5010_50101201_5_dialog_content = "Ahaha... Aku tahu aku belum terlalu terlambat!",
  ui_story_5010_50101201_6_dialog_content = "Ah...! Tu-Tunggu, mundurlah! Masih ada hal lain yang harus kuurus!",
  ui_story_5010_50101201_7_dialog_content = "Ini dokumen pengalihan kepemilikan untuk semua aset Caelestite, PlayerName. Ini harus kautandatangani.",
  ui_story_5010_50101201_8_dialog_content = "Selain itu, sesuai instruksi Shadowlord... Kami ingin menawarkan Anda <color=#FFB400>komponen ruang simulasi</color> dari pelelangan, gratis, sebagai tanda terima kasih kami.",
  ui_story_5010_50101201_9_dialog_content = "Luke dari White Flame Mercenaries sudah setuju untuk mengantarkan komponen itu ke Eraveil dalam waktu dekat ini.",
  ui_story_5010_50101201_10_dialog_content = "Luke! Kau juga ada di sini?",
  ui_story_5010_50101201_11_dialog_content = "Kalian berdua, kita bertemu lagi.",
  ui_story_5010_50101201_12_dialog_content = "Maaf, aku menyela reuni kalian yang mengharukan ini.",
  ui_story_5010_50101201_13_dialog_content = "Pittman? Apakah persidangannya sudah selesai?",
  ui_story_5010_50101201_14_dialog_content = "Tidak juga... Aku kemari untuk berpamitan. Aku diperintahkan mengawal Rhein kembali ke Lumopolis untuk melanjutkan persidangannya.",
  ui_story_5010_50101201_15_dialog_content = "Tapi, ajaib sekali dia berhasil selamat...",
  ui_story_5010_50101201_16_dialog_content = "Tunggu. Rhein adalah warga Umbraton; apa hakmu untuk membawanya ke Lumopolis?",
  ui_story_5010_50101201_17_dialog_content = "Maafkan aku... Tapi, perintah ini diberikan oleh seseorang yang posisinya jauh lebih tinggi daripada aku.",
  ui_story_5010_50101201_18_dialog_content = "Kalaupun ingin, tetap saja aku tak bisa menolaknya.",
  ui_story_5010_50101201_19_dialog_content = "Tapi...",
  ui_story_5010_50101201_20_dialog_content = "Perlu kutambahkan... Shadowlord sendiri juga sudah menyetujui perintah ini.",
  ui_story_5010_50101201_21_dialog_content = "Benar. Semoga berhasil, Pittman.",
  ui_story_5010_50101201_22_dialog_content = "Sekali lagi, terima kasih atas pengertianmu... Shadowlord.",
  ui_story_5010_50101201_23_dialog_content = "PlayerName, Luke, Lady Bethel... Sampai jumpa lagi.",
  ui_story_5010_50101201_24_dialog_content = "...Ayah.",
  ui_story_5010_50101201_25_dialog_content = "Shadowlord.",
  ui_story_5010_50101201_26_dialog_content = "Hmm... Sepertinya suasana sudah lebih baik.",
  ui_story_5010_50101201_27_dialog_content = "Ah, tapi tentu saja... Cuacanya kan sudah kembali cerah.",
  ui_story_5010_50101201_28_dialog_content = "Istvan!",
  ui_story_5010_50101201_29_dialog_content = "Halo, PlayerName.",
  ui_story_5010_50101201_30_dialog_content = "Aku ingin meminta maaf sebesar-besarnya. Kau terseret ke dalam masalah yang menimpa kota kami, dan peranmu sangat besar.",
  ui_story_5010_50101201_31_dialog_content = "H-Hah? Bukan apa-apa, sungguh... Tak perlu minta maaf!",
  ui_story_5010_50101201_32_dialog_content = "Ayah... Apa nasib Rhein bisa dengan mudah...",
  ui_story_5010_50101201_33_dialog_content = "*Tertawa kecil* Tak lama lagi kau akan memahaminya, Sayang.",
  ui_story_5010_50101201_34_dialog_content = "Me-Memahami apa?",
  ui_story_5010_50101201_35_dialog_content = "Aku bisa paham kalau kita membiarkan musuh mengungkap sendiri konspirasi mereka, kita bisa memulihkan keadaan setelahnya...",
  ui_story_5010_50101201_36_dialog_content = "Tapi, bukankah seharusnya kitalah yang menghukum Rhein atas kejahatan yang dilakukannya?",
  ui_story_5010_50101201_37_dialog_content = "Hah? Kaubilang membiarkan situasi jadi tak terkendali seperti itu adalah \"strategi\"?!",
  ui_story_5010_50101201_38_dialog_content = "Dengan membiarkan Rhein membuka semua kartunya, kita bisa mencegah agar dia tak punya peluang untuk terus menyusun rencana secara rahasia, dan agar dia serta antek-anteknya tak menimbulkan lebih banyak masalah kelak.",
  ui_story_5010_50101201_39_dialog_content = "Tapi, seandainya kita tak bisa mengendalikan situasi pada saat-saat terakhir... Bukankah itu akan memakan sangat banyak korban jiwa?",
  ui_story_5010_50101201_40_dialog_content = "Orang yang berhati baik dan polos tak akan bisa bertahan hidup di Umbraton... Terutama kalau orang itu tak punya kuasa.",
  ui_story_5010_50101201_41_dialog_content = "Mungkin ini adalah ujian bagi Nona Bethel? Lagi pula, aku yakin dia pasti sudah mempertimbangkan matang-matang soal siapa yang akan menggantikan jabatannya...",
  ui_story_5010_50101201_42_dialog_content = "Cukup sudah pembahasan soal itu. Bagaimanapun, aku khawatir kalau kita membiarkan Lumopolis membawa Rhein, mungkin saja hukuman yang dijatuhkan kepadanya jauh lebih ringan daripada yang seharusnya.",
  ui_story_5010_50101201_43_dialog_content = "Itu bukan sebatas kemungkinan; aku justru akan kaget kalau mereka tak memberinya keringanan hukuman.",
  ui_story_5010_50101201_44_dialog_content = "Hah?",
  ui_story_5010_50101201_45_dialog_content = "Kalau mau mengeksekusi atau menjatuhkan hukuman berat kepada penjahat, Umbraton-lah tempat yang tepat. Jadi, buat apa mereka membawanya kembali ke Lumopolis?",
  ui_story_5010_50101201_46_dialog_content = "Rhein kuat... Sangat kuat. Kalau dia tak punya semacam dukungan rahasia dari Lumopolis...",
  ui_story_5010_50101201_47_dialog_content = "Kalaupun dia berhasil mengalahkan kita, dia tak akan bisa bertahan lama sebagai Shadowlord.",
  ui_story_5010_50101201_48_dialog_content = "Kalau para pemain rahasia itu belum ingin Rhein mati, aku yakin mereka pasti tak akan membiarkan dia dieksekusi.",
  ui_story_5010_50101201_49_dialog_content = "Benar, 'kan, Yang Mulia?",
  ui_story_5010_50101201_50_dialog_content = "Aku paham maksudmu, tapi ini topik yang sebaiknya tak usah kubahas.",
  ui_story_5010_50101201_51_dialog_content = "Lady Bethel, saya dapat meyakinkan Anda bahwa keputusan Lord Istvan adalah keputusan yang telah dia pikirkan dengan matang. Tolong jangan terlalu kesal karenanya.",
  ui_story_5010_50101201_52_dialog_content = "Jabatan yang dimilikinya selama bertahun-tahun ini hanya bisa dipegang oleh orang yang punya intuisi tajam dan pikiran jernih.",
  ui_story_5010_50101201_53_dialog_content = "Aku bisa memahaminya, tapi aku masih tak mau menerimanya.",
  ui_story_5010_50101201_54_dialog_content = "Entah itu Lumopolis atau Umbraton... skema mereka semakin dalam setiap hari.",
  ui_story_5010_50101201_55_dialog_content = "Satu hal lagi, PlayerName. Penyelidikanku tentang \"Enhancer\" masih terus berlanjut. Aku yakin aku akan butuh bantuanmu sekali lagi.",
  ui_story_5010_50101201_56_dialog_content = "Pastinya penyelidikanmu tak mudah, 'kan? Orang-orang justru bekerja sama dengan Eclipse, dan...",
  ui_story_5010_50101201_57_dialog_content = "Aku harus memintamu untuk tidak menarik kesimpulan tanpa dasar sebelum kita berhasil memperoleh bukti yang memadai. Butuh kesabaran besar untuk mencari kebenarannya.",
  ui_story_5010_50101201_58_dialog_content = "*Menghela napas* Baiklah.",
  ui_story_5010_50101201_59_dialog_content = "Aku akan terus melacak sisa sekutu Rhein di Umbraton. Kami akan menangkap semua bajingan itu sampai habis tak bersisa.",
  ui_story_5010_50101201_60_dialog_content = "Akibat dari pemberontakan terlalu parah. Jangan sampai terjadi lagi.",
  ui_story_5010_50101201_61_dialog_content = "Bethel, Rhein bukan orang pertama yang menantang Istvan, dan tak akan menjadi yang terakhir.",
  ui_story_5010_50101201_62_dialog_content = "Dilihat dari hasilnya, Istvan cukup kuat untuk menangani situasi ini. Jadi, semua orang harus terus menjaga ketertiban di sini.",
  ui_story_5010_50101201_63_dialog_content = "Semua skuad tentara bayaran, geng, guild...",
  ui_story_5010_50101201_64_dialog_content = "Ah, guild... Omong-omong, Luke, bagaimana kabar keluarga Lin?",
  ui_story_5010_50101201_65_dialog_content = "Aku sudah menyelidikinya. Anggota inti dari keluarga Lin sedang menggali relik misterius, dan mereka tidak akan kembali dalam waktu dekat.",
  ui_story_5010_50101201_66_dialog_content = "Begitu rupanya. Aku harus berterima kasih kepada keluarga Lin jika ada kesempatan.",
  ui_story_5010_50101201_67_dialog_content = "Jika ada informasi apa pun, kami akan melaporkannya kepadamu.",
  ui_story_5010_50101201_68_dialog_content = "Yah, saatnya mengucapkan selamat tinggal kepada kalian semua.",
  ui_story_5010_50101201_69_dialog_content = "Naroxel tersayang:",
  ui_story_5010_50101201_70_dialog_content = "\"Nah, begitulah akhir perjalanan kami ke Umbraton... Meskipun ada hal-hal yang kusesali...\"",
  ui_story_5010_50101201_71_dialog_content = "\"Aku senang karena berhasil mendapatkan komponen ruang simulasi itu...\"",
  ui_story_5010_50101201_72_dialog_content = "\"Fungsi utamanya masih belum diketahui. Aku sudah menghubungi beberapa pakar sains dan teknologi...\"",
  ui_story_5010_50101201_73_dialog_content = "\"Sekali lagi terima kasih, Naroxel. Dan semoga alam menjagamu.\"",
  ui_story_5010_50101201_74_dialog_content = "\"Dari temanmu, PlayerName.\""
}
return config
